INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C1','kor',1,2,'u7',1,'설명을 듣고 무엇을 하라는 것인지 이해하기 — 만들기 시간 화면 설명(색종이를 반으로 접기·자르기)처럼 무엇을 어떻게 하라는 것인지 잘 듣고 이해하며, 장난감 조립·음식 만들기·청소기 조립 설명서처럼 설명하는 글이 무엇을 알려 주는지 알기',ARRAY['2국01-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C2','kor',1,2,'u7',3,'제목과 되풀이 낱말로 설명하는 대상 찾기 — 「독도」처럼 제목을 실마리로 살피고 되풀이해 나오는 낱말을 찾아 글이 무엇을 설명하는지(화제) 잡기, 제목이 늘 대상과 같지는 않음을 알기',ARRAY['2국02-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C3','kor',1,2,'u7',5,'문단을 합쳐 글 전체가 설명하는 것 찾기 — 「자연은 발명왕」·「요술쟁이 바다 생물」처럼 제목에 구체적인 대상이 나오지 않는 글에서 문단마다 소개하는 것을 보고 합쳐서 생각하기, 제목의 뜻 짐작하기',ARRAY['2국02-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C4','kor',1,2,'u7',5,'글을 읽고 새롭게 안 점 말하기 — 「독도」(동도·서도에 있는 것)·「자연은 발명왕」(문어 빨판·민들레씨·도꼬마리)에서 글에 적힌 내용으로 새롭게 안 점을 찾아 밑줄 긋고 말하기, 글에 없는 것을 지어내거나 내용을 뒤바꾸지 않기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C5','kor',1,2,'u7',7,'겪은 일을 정리하는 방법 알기 — 「진짜 일 학년 책가방을 지켜라!」의 준수처럼 언제·어디에서 있었던 일인지·무슨 일이었는지·그때의 마음을 정리하고, 비슷한 일이나 비슷한 마음이 들었던 자신의 경험을 떠올리기, 평범한 일도 겪은 일임을 알기',ARRAY['2국03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C6','kor',1,2,'u7',7,'마음을 여러 말로 나타내기 — 「즐거웠다·재미있었다」에서 그치지 않고 조마조마했다·짭조름한 우엉이 많아서 맛있었다처럼 까닭을 넣어 바꾸어 쓰기, 마음말과 한 일을 나타내는 말 가르기, 표정과 어울리는 감정 낱말 고르기(기초 다지기)',ARRAY['2국03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C7','kor',1,2,'u7',10,'겪은 일이 잘 드러나는 글 쓰기 — 겪은 일과 관련 있는 것을 떠올려(보기: 현장 체험 학습 — 버스·수목원·김밥·술래잡기) 글로 쓸 내용을 고르고, 많이 늘어놓기보다 일이 일어난 차례대로 그때의 마음과 함께 쓰기, 친구와 바꾸어 읽으며 잘 드러난 곳을 칭찬하기',ARRAY['2국03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u7-C8','kor',1,2,'u7',12,'겪은 일을 넣어 칭찬하는 글 쓰기 — 언제·칭찬하고 싶은 일·그때의 마음 세 칸으로 정리해 왜 칭찬하는지 겪은 일로 쓰고, 평가가 아닌 진심 어린 칭찬을 하며, 친구뿐 아니라 가족·선생님·자신에게도 쓰기',ARRAY['2국03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X01','kor',1,'u7',ARRAY['K1-2-u7-C1']::text[],'설명하는 글(설명서·놀이 방법)과 일기·편지를 가르지 못하거나, 설명하는 글이 무엇을 알려 주는지 잡지 못한다','「읽고 나면 무엇을 어떻게 하는지 알게 되나?」 한 가지 물음으로 글을 둘로 나누어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X02','kor',1,'u7',ARRAY['K1-2-u7-C1','K1-2-u7-C2']::text[],'설명을 끝까지 듣지 않거나 대충 읽어도 된다고 여기고, 글의 길이·글자 수처럼 내용과 상관없는 것부터 본다','만들기 설명을 한 줄 빼고 들려준 뒤 해 보게 하기 — 「어디서 막혔나요?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X03','kor',1,'u7',ARRAY['K1-2-u7-C2','K1-2-u7-C3']::text[],'제목에 나온 낱말을 그대로 설명하는 대상이라고 여긴다(「발명왕」·「요술쟁이」를 대상으로 고름)','제목을 손으로 가리고 문단만 읽게 한 뒤 「무엇에 대한 글이었나?」 — 그다음 제목을 열어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X04','kor',1,'u7',ARRAY['K1-2-u7-C2','K1-2-u7-C3']::text[],'한 문단에만 나온 것(문어·민들레씨·등대)을 글 전체가 설명하는 것으로 고른다','문단마다 손가락을 짚으며 「이 문단에도 나오나?」 세어 보기 — 모든 문단에 걸치는 것이 전체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X05','kor',1,'u7',ARRAY['K1-2-u7-C2']::text[],'되풀이해 나오는 낱말을 찾지 못하거나, 찾는 방법(제목·되풀이 낱말)을 쓰지 않는다','문장마다 같은 낱말에 같은 색 동그라미 — 동그라미가 가장 많은 낱말이 실마리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X06','kor',1,'u7',ARRAY['K1-2-u7-C3','K1-2-u7-C4','K1-2-u7-C5']::text[],'글이나 겪은 일의 내용을 잘못 읽거나 뒤섞는다(동도와 서도에 있는 것 뒤바꾸기, 인물이 한 일 엇갈리기)','「그 내용이 몇째 줄에 있나요?」 줄을 짚게 하고 그 줄만 다시 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X07','kor',1,'u7',ARRAY['K1-2-u7-C4']::text[],'글에 없는 것을 지어내어 새롭게 안 점이라고 말한다','「글 어디에 있었어?」 — 줄을 찾지 못하면 새롭게 안 점이 아니라 내 생각이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X08','kor',1,'u7',ARRAY['K1-2-u7-C5']::text[],'아직 하지 않은 일·하고 싶은 일을 겪은 일로 여긴다','「이미 있었던 일인가요?」 — 어제·오늘·지난번을 붙여 말이 되는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X09','kor',1,'u7',ARRAY['K1-2-u7-C5','K1-2-u7-C7']::text[],'겪은 일은 생일·여행처럼 특별한 일이어야 한다고 여겨 날마다 있는 일을 글감에서 뺀다','등굣길·급식 시간처럼 오늘 마음이 움직였던 순간 세 가지를 찾아보기 — 그게 다 글감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X10','kor',1,'u7',ARRAY['K1-2-u7-C5','K1-2-u7-C8']::text[],'정리할 칸(언제·어디에서·무슨 일·그때의 마음) 가운데 하나를 빠뜨리거나, 글자 수처럼 정리와 상관없는 것을 넣는다','칸에 손가락을 짚으며 「언제? 어디서? 무슨 일? 마음은?」 차례로 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X11','kor',1,'u7',ARRAY['K1-2-u7-C6','K1-2-u7-C7']::text[],'마음을 「즐거웠다·재미있었다·좋았다」 한마디로 그치거나 같은 말을 되풀이해 늘인다','「왜 재미있었어?」 한 번 더 묻고, 그 대답을 마음말 앞에 붙여 다시 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X12','kor',1,'u7',ARRAY['K1-2-u7-C6','K1-2-u7-C5']::text[],'마음을 나타내는 말과 한 일을 나타내는 말(나누어 먹었다·데려다주었다)을 가르지 못한다','「몸이 한 것이야, 마음이 느낀 것이야?」 두 칸 상자에 낱말 카드 나누어 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X13','kor',1,'u7',ARRAY['K1-2-u7-C6']::text[],'표정·장면과 감정 낱말을 어긋나게 잇는다(웃는 얼굴에 「힘들어요」, 우는 얼굴에 「신나요」)','그 표정을 몸으로 흉내 내 보고 「지금 마음이 어때?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X14','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'있었던 일을 많이 늘어놓을수록 잘 쓴 글이라고 여긴다','232쪽 보기 글과 233쪽 예시 글을 나란히 읽고 「어느 쪽이 눈에 그려지나?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X16','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'글감을 고를 때 하고 싶은 말이 없는 일·남이 겪은 일을 고르거나, 겪은 일과 상관없는 것을 떠올린다','「이 일을 친구들에게 들려주고 싶어?」 — 들려줄 까닭이 있는 일이 글감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X17','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'일이 일어난 차례를 뒤섞어 쓴다','일을 카드 한 장에 하나씩 적어 처음·가운데·끝 순서로 늘어놓은 뒤 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X18','kor',1,'u7',ARRAY['K1-2-u7-C7']::text[],'친구 글을 돌려 읽을 때 틀린 글자·글의 길이만 보고 좋은 점을 찾지 않는다','「좋은 표현 하나 → 마음이 드러난 곳 하나」를 먼저 말한 뒤 고칠 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X19','kor',1,'u7',ARRAY['K1-2-u7-C8']::text[],'칭찬을 견주거나 평가하는 말로 쓰거나, 「착해·최고야」처럼 뭉뚱그리거나, 겉모습·가진 물건을 칭찬거리로 고른다','「그 사람이 한 일 중에 고마웠던 일은?」 — 한 일이 들어가야 다른 친구도 「맞아!」 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u7-X20','kor',1,'u7',ARRAY['K1-2-u7-C8']::text[],'칭찬하는 글은 같은 반 친구에게만 쓸 수 있다고 여긴다','가족·선생님·이웃, 그리고 나 자신까지 — 나를 도와준 사람을 한 명씩 떠올려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#1','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',1,'mc','auto','『국어』 215쪽 생각 열기 — 그림 속 아이는 무엇을 하고 있을까요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"『국어』 215쪽 생각 열기 — 그림 속 아이는 무엇을 하고 있을까요?","options":[{"t":"글을 살펴보며 장난감을 만들고 있어요","correct":true},{"t":"낮잠을 자고 있어요","mis":"K1-2-u7-X06"},{"t":"그림을 그리고 있어요","mis":"K1-2-u7-X06"}],"explanation":["종이에 적힌 글을 보며 장난감을 만들어요.","그림 속 장난감 조각을 살펴봐요.","지도서 280쪽이에요."],"asset":{"type":"scene","icon":"👧📄🧩","text":"『국어』 215쪽 — 아이가 종이를 펼쳐 보며 장난감 조각을 맞추고 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#2','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',1,'mc','auto','그림 속 아이가 읽고 있는 글은 무엇에 대한 글일까요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":2,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"그림 속 아이가 읽고 있는 글은 무엇에 대한 글일까요?","options":[{"t":"장난감 만들기에 대한 설명서","correct":true},{"t":"옛날이야기 책","mis":"K1-2-u7-X01"},{"t":"친구가 보낸 편지","mis":"K1-2-u7-X01"}],"explanation":["장난감을 어떻게 만드는지 알려 주는 설명서예요.","이야기책이나 편지가 아니에요.","지도서 280쪽이에요."],"asset":{"type":"scene","icon":"👧📄🧩","text":"『국어』 215쪽 — 아이가 종이를 펼쳐 보며 장난감 조각을 맞추고 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#3','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',1,'mc','auto','『국어』 217쪽 (1) — 만들기 시간에 두 아이는 무엇을 하고 있나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":3,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 (1) — 만들기 시간에 두 아이는 무엇을 하고 있나요?","options":[{"t":"색종이를 접고 있어요","correct":true},{"t":"공을 차고 있어요","mis":"K1-2-u7-X06"},{"t":"밥을 먹고 있어요","mis":"K1-2-u7-X06"}],"explanation":["만들기 시간에 색종이를 접어요.","216쪽 그림을 살펴봐요.","예시 답안이에요."],"asset":{"type":"passage","lines":["① 색종이를 뒤집어 놓고 반으로 접으세요.","② 접은 색종이를 가위로 자르세요."],"title":"『국어』 216쪽 — 만들기 시간 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#4','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',1,'mc','auto','『국어』 216쪽 — 화면의 첫 번째 설명은 무엇을 하라고 하나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":4,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"『국어』 216쪽 — 화면의 첫 번째 설명은 무엇을 하라고 하나요?","options":[{"t":"색종이를 뒤집어 놓고 반으로 접으라고 해요","correct":true},{"t":"색종이를 가위로 자르라고 해요","mis":"K1-2-u7-X06"},{"t":"색종이에 그림을 그리라고 해요","mis":"K1-2-u7-X06"}],"explanation":["첫 번째는 뒤집어 반으로 접기예요.","자르기는 두 번째 설명이에요.","216쪽이에요."],"asset":{"type":"passage","lines":["① 색종이를 뒤집어 놓고 반으로 접으세요.","② 접은 색종이를 가위로 자르세요."],"title":"『국어』 216쪽 — 만들기 시간 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#5','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'mc','auto','『국어』 217쪽 (2) — 「무엇을 자르지?」 하고 묻던 아이가 만들기를 잘하려면 어떻게 해야 하나요?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":5,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"『국어』 217쪽 (2) — 「무엇을 자르지?」 하고 묻던 아이가 만들기를 잘하려면 어떻게 해야 하나요?","options":[{"t":"무엇을 어떻게 하라는 것인지 설명을 듣고 내용을 이해해야 해요","correct":true},{"t":"친구보다 빨리 만들어야 해요","mis":"K1-2-u7-X02"},{"t":"설명을 듣지 않고 마음대로 만들어요","mis":"K1-2-u7-X02"}],"explanation":["설명을 잘 듣고 이해해야 해요.","빠르기나 마음대로 하기가 아니에요.","217쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"화면","text":"접은 색종이를 가위로 자르세요."},{"who":"여자아이","text":"무엇을 자르지?"},{"who":"남자아이","text":"아하, 이번에는 색종이를 반으로 잘라야 하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#6','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'match','auto','『국어』 217쪽 2번 — 누가 무엇을 하려고 설명서를 읽었는지 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u7-C1","difficulty":2,"kind":"match","stem":"『국어』 217쪽 2번 — 누가 무엇을 하려고 설명서를 읽었는지 이어 보세요.","pairs":[{"l":"엄마","r":"배달된 재료로 음식을 만드셨어요"},{"l":"아빠","r":"새로 산 청소기를 조립하셨어요"},{"l":"그림 속 아이","r":"장난감을 만들었어요"}],"mis":"K1-2-u7-X06","explanation":["누가 언제 설명서를 읽었는지 이어요.","무엇을 만들 때 설명하는 글을 읽어요.","217쪽 2번이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"집에 음식 만들기 재료가 배달되었는데, 엄마께서 거기에 있는 설명서를 따라 음식을 만드시는 것을 본 적이 있어."},{"who":"친구 2","text":"나는 아빠께서 새로 산 청소기를 설명서를 따라서 조립하시는 것을 본 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#7','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'mc','auto','무엇을 어떻게 하는지 알려 주는 글은?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":7,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"무엇을 어떻게 하는지 알려 주는 글은?","options":[{"t":"장난감 조립 설명서","correct":true},{"t":"내가 쓴 그림일기","mis":"K1-2-u7-X01"},{"t":"할머니께 쓴 편지","mis":"K1-2-u7-X01"}],"explanation":["설명서는 무엇을 어떻게 하는지 알려 줘요.","그림일기와 편지는 설명하는 글이 아니에요.","지도서 281쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#8','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'ox','auto','설명서는 차례를 건너뛰고 대충 읽어도 돼요.',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":8,"concept":"K1-2-u7-C1","difficulty":2,"kind":"ox","stem":"설명서는 차례를 건너뛰고 대충 읽어도 돼요.","answer":"X","reason_options":[{"t":"차례를 놓치면 무엇을 어떻게 하는지 알 수 없으니까","correct":true},{"t":"그림만 보면 다 알 수 있으니까","mis":"K1-2-u7-X02"}],"mis":"K1-2-u7-X02","explanation":["설명하는 글은 차례대로 자세히 읽어요.","대상·차례를 살펴요.","지도서 281쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_basic#9','kor',1,2,'u7','L01','g1_2_kor_u7_L01_basic','lesson_basic','K1-2-u7-C1',2,'mc','auto','「아하, 이번에는 색종이를 반으로 잘라야 하는구나.」 하고 말한 아이는 무엇을 잘했나요?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":9,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"「아하, 이번에는 색종이를 반으로 잘라야 하는구나.」 하고 말한 아이는 무엇을 잘했나요?","options":[{"t":"설명을 잘 듣고 무엇을 할지 알았어요","correct":true},{"t":"가위를 빨리 집었어요","mis":"K1-2-u7-X02"},{"t":"친구 것을 보고 따라 했어요","mis":"K1-2-u7-X02"}],"explanation":["설명을 듣고 내용을 이해했어요.","그래서 만들기를 잘했어요.","216쪽이에요."],"asset":{"type":"speech","turns":[{"who":"화면","text":"접은 색종이를 가위로 자르세요."},{"who":"여자아이","text":"무엇을 자르지?"},{"who":"남자아이","text":"아하, 이번에는 색종이를 반으로 잘라야 하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
