INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#5','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',3,'mc','auto','다음 가운데 무엇을 설명하는 글의 문장은?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":5,"concept":"K1-2-u7-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 무엇을 설명하는 글의 문장은?","options":[{"t":"독도는 우리나라 동쪽 끝에 위치한 섬입니다.","correct":true},{"t":"오늘 친구와 놀아서 즐거웠다.","mis":"K1-2-u7-X01"},{"t":"할머니, 보고 싶어요.","mis":"K1-2-u7-X01"}],"explanation":["독도가 어떤 섬인지 알려 줘요.","일기·편지 문장은 설명하는 글이 아니에요.","218쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#6','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',3,'mc','auto','이 단원에서 배울 두 가지로 알맞은 것은?',ARRAY['K1-2-u7-X01','K1-2-u7-X02']::text[],false,'{"seq":6,"concept":"K1-2-u7-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 배울 두 가지로 알맞은 것은?","options":[{"t":"무엇을 설명하는지 생각하며 글 읽기와 겪은 일 쓰기","correct":true},{"t":"시를 외우고 노래 부르기","mis":"K1-2-u7-X01"},{"t":"글자 수를 세고 빨리 읽기","mis":"K1-2-u7-X02"}],"explanation":["설명하는 글 읽기와 겪은 일 쓰기예요.","단원 학습 내용을 떠올려요.","214쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#7','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',3,'mc','auto','엄마께서 설명서를 따라 음식을 만드신 까닭으로 알맞은 것은?',ARRAY['K1-2-u7-X02','K1-2-u7-X01']::text[],false,'{"seq":7,"concept":"K1-2-u7-C1","difficulty":3,"kind":"mc","stem":"엄마께서 설명서를 따라 음식을 만드신 까닭으로 알맞은 것은?","options":[{"t":"음식을 어떻게 만드는지 알기 위해서","correct":true},{"t":"설명서가 예뻐서","mis":"K1-2-u7-X02"},{"t":"설명서를 버리려고","mis":"K1-2-u7-X01"}],"explanation":["설명서는 만드는 방법을 알려 줘요.","그래서 따라 하며 만들어요.","217쪽 2번이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"집에 음식 만들기 재료가 배달되었는데, 엄마께서 거기에 있는 설명서를 따라 음식을 만드시는 것을 본 적이 있어."},{"who":"친구 2","text":"나는 아빠께서 새로 산 청소기를 설명서를 따라서 조립하시는 것을 본 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#8','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',4,'sa','auto','『국어』 215쪽 — 장난감을 어떻게 만드는지 알려 주는 글을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C1","difficulty":4,"kind":"sa","stem":"『국어』 215쪽 — 장난감을 어떻게 만드는지 알려 주는 글을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["설명서"],"explanation":["장난감 조립 설명서예요.","무엇을 어떻게 하는지 알려 줘요.","215쪽이에요."],"asset":{"type":"scene","icon":"👧📄🧩","text":"『국어』 215쪽 — 아이가 종이를 펼쳐 보며 장난감 조각을 맞추고 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#9','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',4,'essay','teacher','설명서를 보며 무엇을 만들거나 해 본 경험을 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C1","difficulty":4,"kind":"essay","stem":"설명서를 보며 무엇을 만들거나 해 본 경험을 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 설명서를 보며 종이접기로 개구리를 접어 본 적이 있어요. — 무엇을 읽었는지와 무엇을 했는지가 있으면 맞아요.","scoring_points":["무엇을 읽었는지 썼는가","무엇을 했는지 썼는가","완결된 문장인가"]},"explanation":["설명서·놀이 방법을 떠올려요.","무엇을 했는지 써요.","지도서 280쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L01_challenge#10','kor',1,2,'u7','L01','g1_2_kor_u7_L01_challenge','lesson_challenge','K1-2-u7-C1',4,'essay','teacher','「무엇을 자르지?」 하고 묻던 친구에게 만들기를 잘하는 방법을 알려 주는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C1","difficulty":4,"kind":"essay","stem":"「무엇을 자르지?」 하고 묻던 친구에게 만들기를 잘하는 방법을 알려 주는 말을 쓰세요.","answer_guide":{"answer":"예: 선생님 설명을 끝까지 잘 듣고 무엇을 어떻게 하라는 것인지 생각하면 돼. — 설명을 잘 듣고 이해하라는 내용이면 맞아요.","scoring_points":["설명을 잘 들으라고 했는가","무엇을 어떻게 하는지 생각하라고 했는가","완결된 문장인가"]},"explanation":["설명을 이해하는 것이 중요해요.","친구에게 말하듯 써요.","217쪽이에요."],"asset":{"type":"speech","turns":[{"who":"화면","text":"접은 색종이를 가위로 자르세요."},{"who":"여자아이","text":"무엇을 자르지?"},{"who":"남자아이","text":"아하, 이번에는 색종이를 반으로 잘라야 하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#1','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',1,'mc','auto','「독도」 — 이 글의 제목은 무엇인가요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":1,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"「독도」 — 이 글의 제목은 무엇인가요?","options":[{"t":"독도","correct":true},{"t":"동도","mis":"K1-2-u7-X04"},{"t":"등대","mis":"K1-2-u7-X04"}],"explanation":["제목은 「독도」예요.","동도·등대는 글 속에 나오는 것이에요.","219쪽 2번이에요."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#2','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',1,'mc','auto','독도는 어디에 있나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"독도는 어디에 있나요?","options":[{"t":"우리나라 동쪽 끝","correct":true},{"t":"우리나라 서쪽 끝","mis":"K1-2-u7-X06"},{"t":"우리나라 남쪽 끝","mis":"K1-2-u7-X06"}],"explanation":["동쪽 끝에 있는 섬이에요.","첫 문장을 다시 읽어요.","218쪽이에요."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
