INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#4','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',1,'mc','auto','「독도」에서 여러 번 되풀이해 나오는 낱말은?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":4,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"「독도」에서 여러 번 되풀이해 나오는 낱말은?","options":[{"t":"독도","correct":true},{"t":"등대","mis":"K1-2-u7-X04"},{"t":"숙소","mis":"K1-2-u7-X04"}],"explanation":["「독도」가 계속 나와요.","등대·숙소는 한 문단에만 나와요.","지도서 283쪽이에요."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#5','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',2,'mc','auto','『국어』 219쪽 2번 (2) — 이 글은 무엇을 소개하고 있나요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":5,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"『국어』 219쪽 2번 (2) — 이 글은 무엇을 소개하고 있나요?","options":[{"t":"독도의 위치, 동도와 서도에 대한 내용","correct":true},{"t":"독도에 가는 배 시간표","mis":"K1-2-u7-X07"},{"t":"바다에 사는 물고기","mis":"K1-2-u7-X07"}],"explanation":["독도의 위치와 동도·서도를 소개해요.","글에 없는 내용은 고르지 않아요.","219쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#6','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',2,'mc','auto','동도에 있는 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":6,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"동도에 있는 것은?","options":[{"t":"밤에도 불을 밝히는 등대","correct":true},{"t":"주민을 위한 숙소","mis":"K1-2-u7-X06"},{"t":"땅에서 물이 모이는 곳","mis":"K1-2-u7-X06"}],"explanation":["동도에는 등대·배 시설·경비대가 있어요.","숙소와 물이 모이는 곳은 서도에 있어요.","219쪽이에요."],"asset":{"type":"passage","lines":["동도에는 등대와, 배가 드나들 수 있도록 만든 시설이 있습니다.","동도에 있는 등대는 밤에도 불을 밝혀 독도 주변을 지키는 데 도움을 줍니다.","독도를 지키는 경비대도 이곳에 있습니다."],"title":"「독도」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#7','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',2,'mc','auto','서도에 있는 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":7,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"서도에 있는 것은?","options":[{"t":"주민을 위한 숙소","correct":true},{"t":"독도를 지키는 경비대","mis":"K1-2-u7-X06"},{"t":"배가 드나드는 시설","mis":"K1-2-u7-X06"}],"explanation":["서도에는 주민 숙소가 있어요.","경비대와 배 시설은 동도에 있어요.","219쪽이에요."],"asset":{"type":"passage","lines":["서도에는 주민을 위한 숙소가 있습니다.","독도를 사람들에게 널리 알리고 보존하는 일을 하는 독도관리사무소 직원도 독도에 올 때에는 이곳을 이용합니다.","또 서도에는 땅에 스며든 물이 땅 밖으로 모이는 곳이 있습니다.","옛날에는 사람들이 이 물을 썼지만, 요즘은 바닷물을 우리가 먹을 수 있게 바꾼 뒤 그 물을 사용합니다."],"title":"「독도」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#8','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',2,'match','auto','「독도」를 읽고 알맞게 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C4","difficulty":2,"kind":"match","stem":"「독도」를 읽고 알맞게 이어 보세요.","pairs":[{"l":"동도","r":"등대와 경비대가 있는 섬"},{"l":"서도","r":"주민 숙소가 있는 섬"},{"l":"독도","r":"동도와 서도를 합쳐 부르는 이름"}],"mis":"K1-2-u7-X06","explanation":["글에 적힌 대로 이어요.","동도와 서도를 헷갈리지 않아요.","218~219쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#9','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C2',2,'mc','auto','설명하는 대상을 찾는 방법으로 알맞은 것은?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":9,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"설명하는 대상을 찾는 방법으로 알맞은 것은?","options":[{"t":"제목을 살펴보고 되풀이해 나오는 낱말을 찾아요","correct":true},{"t":"마지막 낱말만 봐요","mis":"K1-2-u7-X05"},{"t":"사진의 색깔만 봐요","mis":"K1-2-u7-X05"}],"explanation":["제목과 되풀이 낱말이 실마리예요.","마지막 낱말·사진 색깔로는 알기 어려워요.","지도서 283쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_basic#10','kor',1,2,'u7','L03','g1_2_kor_u7_L03_basic','lesson_basic','K1-2-u7-C4',3,'mc','auto','「독도」를 읽고 새롭게 안 점으로 알맞은 것은?',ARRAY['K1-2-u7-X07','K1-2-u7-X06']::text[],false,'{"seq":10,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「독도」를 읽고 새롭게 안 점으로 알맞은 것은?","options":[{"t":"독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있어요","correct":true},{"t":"독도에는 사람이 한 명도 오지 않아요","mis":"K1-2-u7-X07"},{"t":"서도에 등대가 있어요","mis":"K1-2-u7-X06"}],"explanation":["글에 적힌 내용이에요.","사람이 오지 않는다는 말은 글에 없고, 등대는 동도에 있어요.","219쪽 3번이에요."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#1','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',2,'mc','auto','요즘 독도에서 사용하는 물은?',ARRAY['K1-2-u7-X07','K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"요즘 독도에서 사용하는 물은?","options":[{"t":"바닷물을 먹을 수 있게 바꾼 물","correct":true},{"t":"육지에서 매일 가져온 주스","mis":"K1-2-u7-X07"},{"t":"빗물을 그대로 모은 물","mis":"K1-2-u7-X06"}],"explanation":["바닷물을 먹을 수 있게 바꾸어 써요.","옛날에는 땅에서 모인 물을 썼어요.","219쪽이에요."],"asset":{"type":"passage","lines":["서도에는 주민을 위한 숙소가 있습니다.","독도를 사람들에게 널리 알리고 보존하는 일을 하는 독도관리사무소 직원도 독도에 올 때에는 이곳을 이용합니다.","또 서도에는 땅에 스며든 물이 땅 밖으로 모이는 곳이 있습니다.","옛날에는 사람들이 이 물을 썼지만, 요즘은 바닷물을 우리가 먹을 수 있게 바꾼 뒤 그 물을 사용합니다."],"title":"「독도」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#2','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',2,'mc','auto','동도의 등대는 어떤 도움을 주나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"동도의 등대는 어떤 도움을 주나요?","options":[{"t":"밤에도 불을 밝혀 독도 주변을 지키는 데 도움을 줘요","correct":true},{"t":"주민에게 잠잘 곳을 줘요","mis":"K1-2-u7-X06"},{"t":"땅속 물을 모아 줘요","mis":"K1-2-u7-X06"}],"explanation":["등대는 밤에도 불을 밝혀요.","잠잘 곳과 물은 서도 이야기예요.","219쪽이에요."],"asset":{"type":"passage","lines":["동도에는 등대와, 배가 드나들 수 있도록 만든 시설이 있습니다.","동도에 있는 등대는 밤에도 불을 밝혀 독도 주변을 지키는 데 도움을 줍니다.","독도를 지키는 경비대도 이곳에 있습니다."],"title":"「독도」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
