INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#5','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',3,'mc','auto','지도서 282쪽 — 「독도」처럼 제목에 설명하는 대상이 늘 드러나나요?',ARRAY['K1-2-u7-X03','K1-2-u7-X05']::text[],false,'{"seq":5,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"지도서 282쪽 — 「독도」처럼 제목에 설명하는 대상이 늘 드러나나요?","options":[{"t":"아니요 — 드러나지 않는 글도 많아 글 내용도 살펴봐야 해요","correct":true},{"t":"네 — 제목이 곧 설명하는 대상이에요","mis":"K1-2-u7-X03"},{"t":"제목은 볼 필요가 없어요","mis":"K1-2-u7-X05"}],"explanation":["「독도」는 제목에 대상이 드러나요.","하지만 늘 그렇지는 않아요.","지도서 282쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#6','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',3,'mc','auto','지도서 287쪽 「비사치기」 — 이 글이 설명하는 대상은?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":6,"concept":"K1-2-u7-C2","difficulty":3,"kind":"mc","stem":"지도서 287쪽 「비사치기」 — 이 글이 설명하는 대상은?","options":[{"t":"비사치기","correct":true},{"t":"돌멩이","mis":"K1-2-u7-X04"},{"t":"가위바위보","mis":"K1-2-u7-X04"}],"explanation":["제목과 첫 문장에 「비사치기」가 나와요.","돌멩이·가위바위보는 놀이에 쓰이는 것이에요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#7','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',3,'mc','auto','「비사치기」를 읽고 알 수 있는 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":7,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「비사치기」를 읽고 알 수 있는 것은?","options":[{"t":"세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이겨요","correct":true},{"t":"돌은 손으로만 던져요","mis":"K1-2-u7-X06"},{"t":"혼자서 하는 놀이예요","mis":"K1-2-u7-X06"}],"explanation":["마지막 문장에 이기는 방법이 있어요.","돌은 발등·배·무릎으로 옮기고, 두 편으로 해요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#8','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',4,'sa','auto','「독도」 첫 문단에 여러 번 나오는 낱말이자 이 글이 설명하는 대상을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"「독도」 첫 문단에 여러 번 나오는 낱말이자 이 글이 설명하는 대상을 쓰세요.","answer":["독도"],"explanation":["「독도」가 되풀이해 나와요.","제목도 「독도」예요.","219쪽 2번이에요."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#9','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C4',4,'essay','teacher','『국어』 219쪽 3번 — 「독도」를 다시 읽고 새롭게 안 점을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":4,"kind":"essay","stem":"『국어』 219쪽 3번 — 「독도」를 다시 읽고 새롭게 안 점을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 서도에는 주민을 위한 숙소가 있다는 것을 새롭게 알았어요. — 글에 있는 내용으로 쓰면 맞아요.","scoring_points":["글에 있는 내용인가","「새롭게 알았어요」처럼 안 점을 썼는가","완결된 문장인가"]},"explanation":["밑줄 그은 곳을 떠올려요.","글에 없는 것은 쓰지 않아요.","219쪽 3번이에요."],"asset":{"type":"passage","lines":["서도에는 주민을 위한 숙소가 있습니다.","독도를 사람들에게 널리 알리고 보존하는 일을 하는 독도관리사무소 직원도 독도에 올 때에는 이곳을 이용합니다.","또 서도에는 땅에 스며든 물이 땅 밖으로 모이는 곳이 있습니다.","옛날에는 사람들이 이 물을 썼지만, 요즘은 바닷물을 우리가 먹을 수 있게 바꾼 뒤 그 물을 사용합니다."],"title":"「독도」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L03_challenge#10','kor',1,2,'u7','L03','g1_2_kor_u7_L03_challenge','lesson_challenge','K1-2-u7-C2',4,'essay','teacher','「독도」가 무엇을 설명하는지 찾은 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C2","difficulty":4,"kind":"essay","stem":"「독도」가 무엇을 설명하는지 찾은 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 제목이 「독도」예요. 글에 「독도」라는 낱말이 여러 번 나와요. — 제목과 되풀이 낱말이 있으면 맞아요.","scoring_points":["제목을 썼는가","되풀이 낱말을 썼는가","완결된 문장인가"]},"explanation":["제목과 되풀이 낱말.","두 가지를 써요.","지도서 283쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#1','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',1,'mc','auto','『국어』 223쪽 (1) — 유리창에 인형을 붙일 때 쓰는 물건은 무엇을 본떠 만들었나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"『국어』 223쪽 (1) — 유리창에 인형을 붙일 때 쓰는 물건은 무엇을 본떠 만들었나요?","options":[{"t":"문어의 빨판","correct":true},{"t":"민들레씨","mis":"K1-2-u7-X06"},{"t":"도꼬마리 열매","mis":"K1-2-u7-X06"}],"explanation":["문어의 빨판을 본떴어요.","민들레씨·도꼬마리는 다른 문단이에요.","223쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["유리창에 붙어 있는 인형을 본 적이 있나요?","그것을 붙일 때에 사용하는 물건은 문어의 빨판을 본떠 만들었습니다.","문어는 빨판을 이용해 어디에나 잘 달라붙습니다.","우리가 흔히 쓰는 칫솔걸이도 이것을 본떠 만든 물건입니다."],"title":"「자연은 발명왕」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#2','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',1,'mc','auto','『국어』 223쪽 (2) — 낙하산은 무엇을 본떠 만들었나요?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":2,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"『국어』 223쪽 (2) — 낙하산은 무엇을 본떠 만들었나요?","options":[{"t":"민들레씨","correct":true},{"t":"문어의 빨판","mis":"K1-2-u7-X06"},{"t":"새의 깃털","mis":"K1-2-u7-X07"}],"explanation":["민들레씨를 본떴어요.","새의 깃털은 글에 없어요.","223쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["낙하산은 민들레씨를 본떠 만들었습니다.","민들레씨의 가는 실 끝에는 털이 여러 개 달려 있습니다.","이 털이 있어서 민들레씨는 둥둥 떠서 멀리까지 날아갈 수 있습니다.","또 천천히 땅에 떨어지게 됩니다.","낙하산을 이용하면 비행기에서 안전하게 땅으로 내려올 수 있습니다."],"title":"「자연은 발명왕」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#3','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',1,'mc','auto','『국어』 223쪽 — 이 글의 제목은 무엇인가요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"『국어』 223쪽 — 이 글의 제목은 무엇인가요?","options":[{"t":"자연은 발명왕","correct":true},{"t":"문어의 빨판","mis":"K1-2-u7-X04"},{"t":"낙하산","mis":"K1-2-u7-X04"}],"explanation":["제목은 「자연은 발명왕」이에요.","문어·낙하산은 문단 속 이야기예요.","223쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#4','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',1,'mc','auto','문어의 빨판을 본떠 만든 물건으로 글에 나온 것은?',ARRAY['K1-2-u7-X07','K1-2-u7-X06']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"문어의 빨판을 본떠 만든 물건으로 글에 나온 것은?","options":[{"t":"칫솔걸이","correct":true},{"t":"우산","mis":"K1-2-u7-X07"},{"t":"낙하산","mis":"K1-2-u7-X06"}],"explanation":["칫솔걸이도 빨판을 본떴어요.","낙하산은 민들레씨를 본떴어요.","220쪽이에요."],"asset":{"type":"passage","lines":["유리창에 붙어 있는 인형을 본 적이 있나요?","그것을 붙일 때에 사용하는 물건은 문어의 빨판을 본떠 만들었습니다.","문어는 빨판을 이용해 어디에나 잘 달라붙습니다.","우리가 흔히 쓰는 칫솔걸이도 이것을 본떠 만든 물건입니다."],"title":"「자연은 발명왕」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#5','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',2,'mc','auto','『국어』 223쪽 (3) — 도꼬마리 열매가 새나 짐승의 털에 잘 붙는 까닭은?',ARRAY['K1-2-u7-X07','K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"『국어』 223쪽 (3) — 도꼬마리 열매가 새나 짐승의 털에 잘 붙는 까닭은?","options":[{"t":"열매에 갈고리 모양의 가시가 많이 있어서","correct":true},{"t":"열매가 끈적끈적해서","mis":"K1-2-u7-X07"},{"t":"열매가 아주 가벼워서","mis":"K1-2-u7-X06"}],"explanation":["갈고리 모양 가시가 털에 걸려요.","끈적끈적하다는 말은 글에 없어요.","223쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["숲속을 걷다 보면 옷에 열매가 붙어 있는 경우가 있습니다.","도꼬마리 열매에는 갈고리 모양의 가시가 많이 있습니다.","그래서 새나 짐승의 털에 잘 붙습니다.","이것을 보고 단추나 끈보다 더 쉽게 붙였다 떼었다 할 수 있는 물건을 만들었습니다."],"title":"「자연은 발명왕」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#6','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',2,'mc','auto','『국어』 223쪽 — 이 글에서 소개하는 것은 무엇인가요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":6,"concept":"K1-2-u7-C3","difficulty":2,"kind":"mc","stem":"『국어』 223쪽 — 이 글에서 소개하는 것은 무엇인가요?","options":[{"t":"자연을 본떠 만든 물건","correct":true},{"t":"바다에 사는 생물","mis":"K1-2-u7-X04"},{"t":"숲에서 노는 방법","mis":"K1-2-u7-X04"}],"explanation":["문단마다 자연을 본떠 만든 물건을 소개해요.","한 문단만 보지 않아요.","223쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#7','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',2,'match','auto','자연과 그것을 본떠 만든 물건을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u7-C3","difficulty":2,"kind":"match","stem":"자연과 그것을 본떠 만든 물건을 이어 보세요.","pairs":[{"l":"문어의 빨판","r":"칫솔걸이"},{"l":"민들레씨","r":"낙하산"},{"l":"도꼬마리 열매","r":"붙였다 떼었다 하는 신발 끈"}],"mis":"K1-2-u7-X06","explanation":["문단마다 하나씩 소개해요.","세 문단을 합치면 자연을 본떠 만든 물건이에요.","220~222쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#8','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C4',2,'mc','auto','민들레씨가 둥둥 떠서 멀리까지 날아갈 수 있는 까닭은?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":8,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"민들레씨가 둥둥 떠서 멀리까지 날아갈 수 있는 까닭은?","options":[{"t":"가는 실 끝에 털이 여러 개 달려 있어서","correct":true},{"t":"씨가 아주 무거워서","mis":"K1-2-u7-X06"},{"t":"씨에 날개가 달려 있어서","mis":"K1-2-u7-X07"}],"explanation":["털 덕분에 둥둥 떠요.","날개 이야기는 글에 없어요.","221쪽이에요."],"asset":{"type":"passage","lines":["낙하산은 민들레씨를 본떠 만들었습니다.","민들레씨의 가는 실 끝에는 털이 여러 개 달려 있습니다.","이 털이 있어서 민들레씨는 둥둥 떠서 멀리까지 날아갈 수 있습니다.","또 천천히 땅에 떨어지게 됩니다.","낙하산을 이용하면 비행기에서 안전하게 땅으로 내려올 수 있습니다."],"title":"「자연은 발명왕」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#9','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',2,'ox','auto','「자연은 발명왕」은 제목에 문어·민들레씨 같은 대상이 바로 나와요.',ARRAY['K1-2-u7-X03']::text[],false,'{"seq":9,"concept":"K1-2-u7-C3","difficulty":2,"kind":"ox","stem":"「자연은 발명왕」은 제목에 문어·민들레씨 같은 대상이 바로 나와요.","answer":"X","reason_options":[{"t":"제목에 구체적인 대상은 없지만 글을 읽으면 무엇을 알려 주는지 알 수 있으니까","correct":true},{"t":"제목에 나온 「발명왕」이 설명하는 대상이니까","mis":"K1-2-u7-X03"}],"mis":"K1-2-u7-X03","explanation":["「독도」와 다른 점이에요.","문단을 읽고 합쳐 생각해요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_basic#10','kor',1,2,'u7','L05','g1_2_kor_u7_L05_basic','lesson_basic','K1-2-u7-C3',3,'mc','auto','제목 「자연은 발명왕」은 무엇을 뜻할까요?',ARRAY['K1-2-u7-X03']::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":3,"kind":"mc","stem":"제목 「자연은 발명왕」은 무엇을 뜻할까요?","options":[{"t":"자연을 본떠 여러 가지 물건을 만들 수 있다는 뜻","correct":true},{"t":"발명왕이라는 사람의 이름","mis":"K1-2-u7-X03"},{"t":"자연이 상을 받았다는 뜻","mis":"K1-2-u7-X03"}],"explanation":["자연이 발명의 본보기가 된다는 뜻이에요.","문단 내용과 제목을 이어 봐요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#1','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',2,'mc','auto','낙하산을 이용하면 무엇을 할 수 있나요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":1,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"낙하산을 이용하면 무엇을 할 수 있나요?","options":[{"t":"비행기에서 안전하게 땅으로 내려올 수 있어요","correct":true},{"t":"바닷속 깊이 들어갈 수 있어요","mis":"K1-2-u7-X07"},{"t":"높은 나무에 오를 수 있어요","mis":"K1-2-u7-X07"}],"explanation":["천천히 떨어지는 민들레씨처럼 안전하게 내려와요.","글에 있는 내용으로 골라요.","221쪽이에요."],"asset":{"type":"passage","lines":["낙하산은 민들레씨를 본떠 만들었습니다.","민들레씨의 가는 실 끝에는 털이 여러 개 달려 있습니다.","이 털이 있어서 민들레씨는 둥둥 떠서 멀리까지 날아갈 수 있습니다.","또 천천히 땅에 떨어지게 됩니다.","낙하산을 이용하면 비행기에서 안전하게 땅으로 내려올 수 있습니다."],"title":"「자연은 발명왕」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#2','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',2,'mc','auto','도꼬마리 열매를 보고 만든 물건은 무엇보다 더 쉽게 붙였다 떼었다 할 수 있나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C4","difficulty":2,"kind":"mc","stem":"도꼬마리 열매를 보고 만든 물건은 무엇보다 더 쉽게 붙였다 떼었다 할 수 있나요?","options":[{"t":"단추나 끈","correct":true},{"t":"풀이나 테이프","mis":"K1-2-u7-X06"},{"t":"못이나 망치","mis":"K1-2-u7-X06"}],"explanation":["단추나 끈보다 쉽게 붙였다 떼어요.","신발·붕대·케이블 정리 끈 사진이 있어요.","222쪽이에요."],"asset":{"type":"passage","lines":["숲속을 걷다 보면 옷에 열매가 붙어 있는 경우가 있습니다.","도꼬마리 열매에는 갈고리 모양의 가시가 많이 있습니다.","그래서 새나 짐승의 털에 잘 붙습니다.","이것을 보고 단추나 끈보다 더 쉽게 붙였다 떼었다 할 수 있는 물건을 만들었습니다."],"title":"「자연은 발명왕」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#3','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',3,'error','auto','한 친구가 「이 글은 문어를 설명해요.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":3,"kind":"error","stem":"한 친구가 「이 글은 문어를 설명해요.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"첫 문단만 보았어요 — 문단을 합치면 자연을 본떠 만든 물건이에요","correct":true,"mis_target":"K1-2-u7-X04"},{"t":"잘 말했어요","mis":"K1-2-u7-X04"},{"t":"제목을 보고 「발명왕」이라고 해야 해요","mis":"K1-2-u7-X03"}],"explanation":["문어는 첫 문단에만 나와요.","모든 문단에 걸치는 것을 찾아요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#4','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',3,'error','auto','한 친구가 「이 글은 발명왕이라는 사람을 설명해요.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":4,"concept":"K1-2-u7-C3","difficulty":3,"kind":"error","stem":"한 친구가 「이 글은 발명왕이라는 사람을 설명해요.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"제목 낱말만 보았어요 — 문단을 읽으면 자연을 본떠 만든 물건이에요","correct":true,"mis_target":"K1-2-u7-X03"},{"t":"잘 말했어요","mis":"K1-2-u7-X03"},{"t":"둘째 문단의 민들레씨라고 해야 해요","mis":"K1-2-u7-X04"}],"explanation":["제목만 보고 답하지 않아요.","문단을 함께 읽어요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#5','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',3,'mc','auto','지도서 287쪽 「요술쟁이 바다 생물」 — 이 글이 설명하는 대상은?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":5,"concept":"K1-2-u7-C3","difficulty":3,"kind":"mc","stem":"지도서 287쪽 「요술쟁이 바다 생물」 — 이 글이 설명하는 대상은?","options":[{"t":"문어","correct":true},{"t":"요술쟁이","mis":"K1-2-u7-X03"},{"t":"모래","mis":"K1-2-u7-X04"}],"explanation":["모든 문장이 문어 이야기예요.","「요술쟁이」는 제목의 말, 모래는 한 문장에만 나와요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#6','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',3,'mc','auto','「요술쟁이 바다 생물」에서 문어가 몸을 위장하는 까닭은?',ARRAY['K1-2-u7-X07','K1-2-u7-X06']::text[],false,'{"seq":6,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「요술쟁이 바다 생물」에서 문어가 몸을 위장하는 까닭은?","options":[{"t":"위험을 피하고 먹이를 쉽게 잡으려고","correct":true},{"t":"친구와 놀려고","mis":"K1-2-u7-X07"},{"t":"모래를 먹으려고","mis":"K1-2-u7-X06"}],"explanation":["마지막 문장에 까닭이 있어요.","글에 없는 까닭은 고르지 않아요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#7','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',3,'mc','auto','「자연은 발명왕」을 읽고 새롭게 안 점으로 알맞은 것은?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":7,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「자연은 발명왕」을 읽고 새롭게 안 점으로 알맞은 것은?","options":[{"t":"칫솔걸이도 문어의 빨판을 본떠 만들었어요","correct":true},{"t":"낙하산은 도꼬마리 열매를 본떠 만들었어요","mis":"K1-2-u7-X06"},{"t":"문어는 하늘을 날 수 있어요","mis":"K1-2-u7-X07"}],"explanation":["글에 적힌 내용이에요.","낙하산은 민들레씨, 문어가 난다는 말은 없어요.","223쪽 글과 연결하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#8','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',4,'sa','auto','「자연은 발명왕」 세 문단을 합쳐 이 글이 소개하는 것을 「자연을 본떠 만든 (    )」으로 쓸 때 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C3","difficulty":4,"kind":"sa","stem":"「자연은 발명왕」 세 문단을 합쳐 이 글이 소개하는 것을 「자연을 본떠 만든 (    )」으로 쓸 때 빈칸에 알맞은 낱말을 쓰세요.","answer":["물건"],"explanation":["자연을 본떠 만든 물건이에요.","세 문단에 공통으로 나와요.","223쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#9','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C4',4,'essay','teacher','『국어』 223쪽 글과 연결하기 — 「자연은 발명왕」을 읽고 새롭게 안 점을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":4,"kind":"essay","stem":"『국어』 223쪽 글과 연결하기 — 「자연은 발명왕」을 읽고 새롭게 안 점을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 낙하산이 민들레씨를 본떠 만든 것이라는 것을 새롭게 알았어요. — 글에 있는 내용으로 쓰면 맞아요.","scoring_points":["글에 있는 내용인가","새롭게 안 점을 썼는가","완결된 문장인가"]},"explanation":["밑줄 그은 곳을 떠올려요.","글에 없는 것은 쓰지 않아요.","223쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L05_challenge#10','kor',1,2,'u7','L05','g1_2_kor_u7_L05_challenge','lesson_challenge','K1-2-u7-C3',4,'essay','teacher','지도서 286쪽 — 연잎 표면의 작은 돌기를 본떠 물이 스며들지 않는 우산을 만들었어요. 이 이야기를 「자연은 발명왕」의 한 문단처럼 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C3","difficulty":4,"kind":"essay","stem":"지도서 286쪽 — 연잎 표면의 작은 돌기를 본떠 물이 스며들지 않는 우산을 만들었어요. 이 이야기를 「자연은 발명왕」의 한 문단처럼 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 비가 와도 연잎은 잘 젖지 않습니다. 연잎 표면을 본떠 물이 스며들지 않는 우산을 만들었습니다. — 자연과 본떠 만든 물건이 함께 있으면 맞아요.","scoring_points":["자연(연잎)을 썼는가","본떠 만든 물건(우산)을 썼는가","두 문장으로 썼는가"]},"explanation":["문단마다 자연과 물건이 짝을 이뤄요.","같은 틀로 써 봐요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#1','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','준수가 잃어버린 것은 무엇인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"준수가 잃어버린 것은 무엇인가요?","options":[{"t":"필통","correct":true},{"t":"운동화","mis":"K1-2-u7-X06"},{"t":"우산","mis":"K1-2-u7-X06"}],"explanation":["준수는 필통을 잃어버렸어요.","그래서 연필도 사라졌어요.","지도서 290쪽 활용 질문이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#2','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','준수가 필통을 잃어버린 것은 몇 번째인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"준수가 필통을 잃어버린 것은 몇 번째인가요?","options":[{"t":"세 번째","correct":true},{"t":"첫 번째","mis":"K1-2-u7-X06"},{"t":"다섯 번째","mis":"K1-2-u7-X06"}],"explanation":["벌써 세 번째예요.","그래서 엄마께 말하기 걱정되었어요.","지도서 290쪽이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#3','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',1,'mc','auto','준수가 새 필통을 잃어버리지 않으려고 한 일은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":3,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"준수가 새 필통을 잃어버리지 않으려고 한 일은?","options":[{"t":"필통에 큼직한 이름표를 붙였어요","correct":true},{"t":"필통을 집에 두고 다녔어요","mis":"K1-2-u7-X06"},{"t":"필통을 친구에게 맡겼어요","mis":"K1-2-u7-X06"}],"explanation":["이름표 붙이기가 비법 1이에요.","226쪽 그림을 살펴봐요.","229쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#4','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',1,'mc','auto','필통은 지켰지만 알림장을 잃어버렸을 때 준수의 마음은?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":4,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"필통은 지켰지만 알림장을 잃어버렸을 때 준수의 마음은?","options":[{"t":"당황스러웠어요","correct":true},{"t":"신났어요","mis":"K1-2-u7-X13"},{"t":"졸렸어요","mis":"K1-2-u7-X13"}],"explanation":["찾는 것이 없어 당황했어요.","228쪽 준수의 표정을 봐요.","229쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#5','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',2,'mc','auto','『국어』 229쪽 3번 — 겪은 일을 정리할 때 생각해야 할 것은?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":2,"kind":"mc","stem":"『국어』 229쪽 3번 — 겪은 일을 정리할 때 생각해야 할 것은?","options":[{"t":"언제, 어디에서 있었던 일인지와 그때의 마음","correct":true},{"t":"그날 입은 옷의 색깔","mis":"K1-2-u7-X10"},{"t":"함께 있던 사람의 나이","mis":"K1-2-u7-X10"}],"explanation":["언제·어디에서·그때의 마음을 생각해요.","옷 색깔·나이는 정리할 것이 아니에요.","229쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#6','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',2,'match','auto','『국어』 229쪽 2번 — 준수가 겪은 일과 그때의 마음을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"『국어』 229쪽 2번 — 준수가 겪은 일과 그때의 마음을 이어 보세요.","pairs":[{"l":"필통에 이름표를 붙였어요","r":"다시는 잃어버리지 않겠다고 다짐했어요"},{"l":"알림장을 잃어버렸어요","r":"당황스러웠어요"},{"l":"필통을 세 번째 잃어버렸어요","r":"엄마께 혼날까 봐 걱정되었어요"}],"mis":"K1-2-u7-X13","explanation":["겪은 일과 마음은 함께 다녀요.","무슨 일이 있었는지 알면 마음을 짐작해요.","229쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#7','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',2,'mc','auto','『국어』 229쪽 3번 — 마음을 더 잘 드러낸 문장은?',ARRAY['K1-2-u7-X11']::text[],false,'{"seq":7,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"『국어』 229쪽 3번 — 마음을 더 잘 드러낸 문장은?","options":[{"t":"준비물을 가져오지 못해서 당황했어","correct":true},{"t":"재미있었어","mis":"K1-2-u7-X11"},{"t":"즐거웠어","mis":"K1-2-u7-X11"}],"explanation":["무엇 때문에 어떤 마음이었는지 있어요.","「재미있었다·즐거웠다」만으로는 덜 드러나요.","229쪽 말풍선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#8','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',2,'mc','auto','준수가 엄마께 또 사 달라고 하기를 망설인 까닭은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":8,"concept":"K1-2-u7-C5","difficulty":2,"kind":"mc","stem":"준수가 엄마께 또 사 달라고 하기를 망설인 까닭은?","options":[{"t":"벌써 세 번째라 엄마께 혼날까 봐","correct":true},{"t":"필통이 너무 비싸서","mis":"K1-2-u7-X06"},{"t":"엄마가 집에 안 계셔서","mis":"K1-2-u7-X06"}],"explanation":["세 번째라 걱정되었어요.","글에 있는 까닭을 찾아요.","지도서 290쪽이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#9','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C5',2,'ox','auto','겪은 일을 떠올릴 때에는 생일잔치·여행처럼 특별한 일만 골라야 해요.',ARRAY['K1-2-u7-X09']::text[],false,'{"seq":9,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"겪은 일을 떠올릴 때에는 생일잔치·여행처럼 특별한 일만 골라야 해요.","answer":"X","reason_options":[{"t":"물건을 잃어버린 일처럼 날마다 있는 일도 겪은 일이니까","correct":true},{"t":"특별한 일만 글로 쓸 수 있으니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["평범한 일도 겪은 일이에요.","지도서 288쪽이에요.","일상에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_basic#10','kor',1,2,'u7','L07','g1_2_kor_u7_L07_basic','lesson_basic','K1-2-u7-C6',3,'mc','auto','다음 가운데 마음을 나타내는 말은?',ARRAY['K1-2-u7-X12']::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"다음 가운데 마음을 나타내는 말은?","options":[{"t":"당황스러웠어요","correct":true},{"t":"가방을 열었어요","mis":"K1-2-u7-X12"},{"t":"필통을 샀어요","mis":"K1-2-u7-X12"}],"explanation":["「당황스러웠어요」는 마음이에요.","가방을 연 것, 필통을 산 것은 한 일이에요.","229쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#1','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',2,'mc','auto','가방을 자신 있게 열어젖힌 준수가 찾은 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":1,"concept":"K1-2-u7-C5","difficulty":2,"kind":"mc","stem":"가방을 자신 있게 열어젖힌 준수가 찾은 것은?","options":[{"t":"알림장","correct":true},{"t":"필통","mis":"K1-2-u7-X06"},{"t":"교과서","mis":"K1-2-u7-X06"}],"explanation":["이번에는 알림장이 없었어요.","필통은 가방에 있었어요.","지도서 290쪽이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#2','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',2,'mc','auto','『국어』 230쪽 (2) — 이 표정에 어울리는 마음은?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":2,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"『국어』 230쪽 (2) — 이 표정에 어울리는 마음은?","options":[{"t":"당황스러웠어요","correct":true},{"t":"신났어요","mis":"K1-2-u7-X13"},{"t":"편안했어요","mis":"K1-2-u7-X13"}],"explanation":["마음은 표정에도 드러나요.","붙임 6으로 표정을 나타내요.","230쪽 4번이에요."],"asset":{"type":"scene","icon":"😳","text":"눈이 동그래지고 얼굴이 빨개진 표정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#3','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',3,'error','auto','한 친구가 정리한 겪은 일이에요. 무엇이 빠졌나요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":3,"concept":"K1-2-u7-C5","difficulty":3,"kind":"error","stem":"한 친구가 정리한 겪은 일이에요. 무엇이 빠졌나요?","options":[{"t":"그때의 마음이 빠졌어요 — 어떤 마음이었는지 써요","correct":true,"mis_target":"K1-2-u7-X10"},{"t":"잘 정리했어요","mis":"K1-2-u7-X10"},{"t":"무슨 일인지가 빠졌어요","mis":"K1-2-u7-X10"}],"explanation":["언제·어디에서·무슨 일은 있어요.","그때의 마음을 더해요.","229쪽 3번이에요."],"asset":{"type":"passage","lines":["언제: 어제 아침","어디에서: 교실","무슨 일: 준비물을 가져오지 못했어요."],"title":"한 친구가 정리한 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
