INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#5','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',3,'mc','auto','『국어』 230쪽 말풍선 — 자신의 경험을 떠올리는 방법으로 알맞은 것은?',ARRAY['K1-2-u7-X09','K1-2-u7-X08']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":3,"kind":"mc","stem":"『국어』 230쪽 말풍선 — 자신의 경험을 떠올리는 방법으로 알맞은 것은?","options":[{"t":"비슷한 일이 아니어도 비슷한 마음이 들었던 다른 경험을 떠올려도 돼요","correct":true},{"t":"준수와 똑같이 필통을 잃어버린 일만 써야 해요","mis":"K1-2-u7-X09"},{"t":"다른 사람이 겪은 일을 내 일처럼 써요","mis":"K1-2-u7-X08"}],"explanation":["비슷한 일도, 비슷한 마음도 좋아요.","남의 일을 내 일처럼 쓰지 않아요.","230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#6','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',3,'mc','auto','「나는 친구와의 약속 시간을 깜빡해서 (    ) 적이 있어.」 빈칸에 어울리는 말은?',ARRAY['K1-2-u7-X13','K1-2-u7-X12']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"「나는 친구와의 약속 시간을 깜빡해서 (    ) 적이 있어.」 빈칸에 어울리는 말은?","options":[{"t":"당황했던","correct":true},{"t":"신이 났던","mis":"K1-2-u7-X13"},{"t":"달려갔던","mis":"K1-2-u7-X12"}],"explanation":["약속을 깜빡하면 당황스러워요.","「달려갔던」은 한 일이에요.","230쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#7','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',3,'mc','auto','『국어』 230쪽 (3) — 이 친구가 말한 그때의 마음은?',ARRAY['K1-2-u7-X12']::text[],false,'{"seq":7,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"『국어』 230쪽 (3) — 이 친구가 말한 그때의 마음은?","options":[{"t":"섭섭했지만 좋았어요","correct":true},{"t":"낙엽 잡기를 했어요","mis":"K1-2-u7-X12"},{"t":"바람이 불었어요","mis":"K1-2-u7-X12"}],"explanation":["섭섭하지만 좋았다는 두 마음이 있어요.","낙엽 잡기는 한 일이에요.","230쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"오늘 친구들과 함께 바람에 떨어지는 낙엽 잡기를 했어. 낙엽을 하나도 못 잡은 건 섭섭하지만, 친구들과 신나게 놀 수 있어서 좋았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#8','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',4,'sa','auto','『국어활동』 85쪽 — 「기분이 좋았다.」를 잘 고친 문장의 빈칸을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#9','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C5',4,'essay','teacher','『국어』 230쪽 4번 — 준수가 겪은 일과 비슷한 자신의 경험을 「나는 ~해서 ~했던 적이 있어.」로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C5","difficulty":4,"kind":"essay","stem":"『국어』 230쪽 4번 — 준수가 겪은 일과 비슷한 자신의 경험을 「나는 ~해서 ~했던 적이 있어.」로 쓰세요.","answer_guide":{"answer":"예: 나는 준비물을 가져오지 못해서 당황했던 적이 있어. — 겪은 일과 그때의 마음이 있으면 맞아요.","scoring_points":["겪은 일을 썼는가","그때의 마음을 썼는가","완결된 문장인가"]},"explanation":["비슷한 일이나 비슷한 마음을 떠올려요.","틀에 맞추어 써요.","230쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L07_challenge#10','kor',1,2,'u7','L07','g1_2_kor_u7_L07_challenge','lesson_challenge','K1-2-u7-C6',4,'essay','teacher','자신이 겪은 일 하나를 골라 언제·어디에서·무슨 일·그때의 마음을 넣어 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":4,"kind":"essay","stem":"자신이 겪은 일 하나를 골라 언제·어디에서·무슨 일·그때의 마음을 넣어 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 어제 쉬는 시간에 교실에서 지우개를 잃어버렸다. 친구가 같이 찾아 주어서 고마웠다. — 네 가지가 들어 있고 마음을 「재미있었다」로만 쓰지 않았으면 맞아요.","scoring_points":["언제·어디에서가 있는가","무슨 일이 있는가","그때의 마음을 까닭과 함께 썼는가"]},"explanation":["네 가지를 빠짐없이.","마음은 다양한 말로.","229쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#1','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',1,'mc','auto','『국어』 231쪽 보기 — 「현장 체험 학습」과 관련 있는 것은?',ARRAY['K1-2-u7-X16']::text[],false,'{"seq":1,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"『국어』 231쪽 보기 — 「현장 체험 학습」과 관련 있는 것은?","options":[{"t":"김밥","correct":true},{"t":"눈사람","mis":"K1-2-u7-X16"},{"t":"수영복","mis":"K1-2-u7-X16"}],"explanation":["김밥·버스·수목원·술래잡기가 있어요.","겪은 일과 상관없는 것은 빼요.","231쪽 보기예요."],"asset":{"type":"passage","lines":["겪은 일: 현장 체험 학습","겪은 일과 관련 있는 것: 버스 · 수목원 · 나무 · 꽃 · 김밥 · 돗자리 · 술래잡기 · 재미"],"title":"『국어』 231쪽 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#2','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',1,'mc','auto','보기 글에서 현장 체험 학습을 간 곳은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"보기 글에서 현장 체험 학습을 간 곳은?","options":[{"t":"수목원","correct":true},{"t":"바닷가","mis":"K1-2-u7-X06"},{"t":"놀이공원","mis":"K1-2-u7-X06"}],"explanation":["수목원으로 갔어요.","글을 다시 읽어요.","232쪽 보기예요."],"asset":{"type":"passage","lines":["현장 체험 학습을 갔다.","버스를 타고 수목원으로 갔다.","수목원에는 많은 나무가 있었다.","점심으로 김밥을 먹었다. 맛있었다.","수목원에서 술래잡기를 했다. 참 재미있었다."],"title":"『국어』 232쪽 보기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
