INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#4','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',1,'mc','auto','글감으로 고를 수 있는 겪은 일은?',ARRAY['K1-2-u7-X08','K1-2-u7-X16']::text[],false,'{"seq":4,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"글감으로 고를 수 있는 겪은 일은?","options":[{"t":"급식 시간에 처음 김치를 먹어 본 일","correct":true},{"t":"내일 갈 소풍","mis":"K1-2-u7-X08"},{"t":"친구가 들려준 여행 이야기","mis":"K1-2-u7-X16"}],"explanation":["평범한 일도 내가 겪은 일이면 글감이에요.","아직 안 한 일, 남이 겪은 일은 아니에요.","지도서 292쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#5','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C6',2,'mc','auto','『국어』 232쪽 (2) 보기 — 「술래잡기가 참 재미있었다.」를 바꾸어 쓴 것은?',ARRAY['K1-2-u7-X12','K1-2-u7-X11']::text[],false,'{"seq":5,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"『국어』 232쪽 (2) 보기 — 「술래잡기가 참 재미있었다.」를 바꾸어 쓴 것은?","options":[{"t":"친구가 나를 잡을까 봐 조마조마했다","correct":true},{"t":"술래잡기를 했다","mis":"K1-2-u7-X12"},{"t":"재미있었다 재미있었다","mis":"K1-2-u7-X11"}],"explanation":["「조마조마했다」로 마음이 생생해요.","같은 말 되풀이나 한 일만으로는 덜 드러나요.","232쪽 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#6','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C6',2,'mc','auto','『국어』 232쪽 (2) — 「김밥이 맛있었다.」를 다양하게 바꾸어 쓴 것은?',ARRAY['K1-2-u7-X12','K1-2-u7-X11']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"『국어』 232쪽 (2) — 「김밥이 맛있었다.」를 다양하게 바꾸어 쓴 것은?","options":[{"t":"짭조름한 우엉이 많아서 김밥이 맛있었다","correct":true},{"t":"김밥을 먹었다","mis":"K1-2-u7-X12"},{"t":"김밥이 맛있었다 맛있었다","mis":"K1-2-u7-X11"}],"explanation":["맛있었던 까닭이 들어 있어요.","「고소한 냄새가 솔솔 나서」도 좋아요.","232쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#7','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'mc','auto','보기 글에서 더 고치면 좋을 점은?',ARRAY['K1-2-u7-X06','K1-2-u7-X14']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"보기 글에서 더 고치면 좋을 점은?","options":[{"t":"느낌을 「맛있었다」, 「재미있었다」로만 짧게 썼어요","correct":true},{"t":"겪은 일이 하나도 없어요","mis":"K1-2-u7-X06"},{"t":"글이 너무 길어요","mis":"K1-2-u7-X14"}],"explanation":["느낌을 다양한 말로 바꾸면 더 잘 드러나요.","겪은 일은 들어 있어요.","지도서 293쪽이에요."],"asset":{"type":"passage","lines":["현장 체험 학습을 갔다.","버스를 타고 수목원으로 갔다.","수목원에는 많은 나무가 있었다.","점심으로 김밥을 먹었다. 맛있었다.","수목원에서 술래잡기를 했다. 참 재미있었다."],"title":"『국어』 232쪽 보기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#8','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'ox','auto','겪은 일이 잘 드러나게 쓰려면 있었던 일을 많이 늘어놓을수록 좋아요.',ARRAY['K1-2-u7-X14']::text[],false,'{"seq":8,"concept":"K1-2-u7-C7","difficulty":2,"kind":"ox","stem":"겪은 일이 잘 드러나게 쓰려면 있었던 일을 많이 늘어놓을수록 좋아요.","answer":"X","reason_options":[{"t":"한 가지 일을 그때의 마음과 함께 자세히 써야 잘 드러나니까","correct":true},{"t":"많이 쓸수록 길어서 좋으니까","mis":"K1-2-u7-X14"}],"mis":"K1-2-u7-X14","explanation":["많이 늘어놓는 것이 아니에요.","지도서 292쪽이에요.","한 가지를 자세히."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#9','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C7',2,'mc','auto','『국어』 233쪽 점검하기 — 친구와 글을 바꾸어 읽을 때 알맞은 것은?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":9,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"『국어』 233쪽 점검하기 — 친구와 글을 바꾸어 읽을 때 알맞은 것은?","options":[{"t":"겪은 일과 느낌이 잘 드러난 부분을 찾아 칭찬해요","correct":true},{"t":"틀린 글자만 찾아 고쳐요","mis":"K1-2-u7-X18"},{"t":"글이 짧다고 놀려요","mis":"K1-2-u7-X18"}],"explanation":["잘 드러난 곳을 찾아 칭찬해요.","틀린 글자에만 매달리지 않아요.","지도서 295쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_basic#10','kor',1,2,'u7','L10','g1_2_kor_u7_L10_basic','lesson_basic','K1-2-u7-C6',3,'mc','auto','예시 글에서 「친구들과 술래잡기도 했다.」 다음에 나오는 마음은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"예시 글에서 「친구들과 술래잡기도 했다.」 다음에 나오는 마음은?","options":[{"t":"친구가 나를 잡을까 봐 조마조마했다","correct":true},{"t":"더 놀고 싶었는데 아쉬웠다","mis":"K1-2-u7-X06"},{"t":"이름이 너무 재미있었다","mis":"K1-2-u7-X06"}],"explanation":["술래잡기 바로 뒤의 마음이에요.","아쉬웠다는 집에 갈 때, 재미있었다는 나무 이름 이야기예요.","233쪽 예시 글이에요."],"asset":{"type":"passage","lines":["1학년이 되어서 처음으로 현장 체험 학습을 갔다. 친구들과 함께 버스를 타고 수목원으로 갔다.","수목원에는 큰 나무와 예쁜 꽃이 많았다.","‘오리나무’와 ‘꽝꽝나무’는 이름이 너무 재미있었다.","화살나무는 줄기가 화살처럼 생겨 신기했다.","점심시간에는 할머니께서 싸 주신 김밥을 친구들과 나누어 먹었다.","김밥 안에 있는 우엉이 달콤하고 짭조름했다.","친구들과 술래잡기도 했다. 친구가 나를 잡을까 봐 조마조마했다.","신나게 놀고 나니 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"『국어』 233쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#1','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',2,'mc','auto','예시 글에서 맨 처음 있었던 일은?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":1,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"예시 글에서 맨 처음 있었던 일은?","options":[{"t":"친구들과 함께 버스를 타고 수목원으로 갔다","correct":true},{"t":"친구들과 술래잡기를 했다","mis":"K1-2-u7-X17"},{"t":"선생님께서 집에 가야 한다고 하셨다","mis":"K1-2-u7-X17"}],"explanation":["일이 일어난 차례대로 썼어요.","술래잡기는 뒤, 집에 가는 일은 끝이에요.","233쪽 예시 글이에요."],"asset":{"type":"passage","lines":["1학년이 되어서 처음으로 현장 체험 학습을 갔다. 친구들과 함께 버스를 타고 수목원으로 갔다.","수목원에는 큰 나무와 예쁜 꽃이 많았다.","‘오리나무’와 ‘꽝꽝나무’는 이름이 너무 재미있었다.","화살나무는 줄기가 화살처럼 생겨 신기했다.","점심시간에는 할머니께서 싸 주신 김밥을 친구들과 나누어 먹었다.","김밥 안에 있는 우엉이 달콤하고 짭조름했다.","친구들과 술래잡기도 했다. 친구가 나를 잡을까 봐 조마조마했다.","신나게 놀고 나니 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"『국어』 233쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#2','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',2,'mc','auto','예시 글에서 「화살나무」를 보고 느낀 마음은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"예시 글에서 「화살나무」를 보고 느낀 마음은?","options":[{"t":"신기했다","correct":true},{"t":"아쉬웠다","mis":"K1-2-u7-X06"},{"t":"조마조마했다","mis":"K1-2-u7-X06"}],"explanation":["줄기가 화살처럼 생겨 신기했어요.","다른 마음은 다른 장면이에요.","233쪽 예시 글이에요."],"asset":{"type":"passage","lines":["1학년이 되어서 처음으로 현장 체험 학습을 갔다. 친구들과 함께 버스를 타고 수목원으로 갔다.","수목원에는 큰 나무와 예쁜 꽃이 많았다.","‘오리나무’와 ‘꽝꽝나무’는 이름이 너무 재미있었다.","화살나무는 줄기가 화살처럼 생겨 신기했다.","점심시간에는 할머니께서 싸 주신 김밥을 친구들과 나누어 먹었다.","김밥 안에 있는 우엉이 달콤하고 짭조름했다.","친구들과 술래잡기도 했다. 친구가 나를 잡을까 봐 조마조마했다.","신나게 놀고 나니 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"『국어』 233쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#3','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',3,'error','auto','예시 글에서 마음을 나타낸 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#4','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'error','auto','한 친구가 쓴 글이에요. 무엇이 잘못되었나요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":4,"concept":"K1-2-u7-C7","difficulty":3,"kind":"error","stem":"한 친구가 쓴 글이에요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 일이 일어난 차례가 섞였어요","correct":true,"mis_target":"K1-2-u7-X17"},{"t":"잘 썼어요","mis":"K1-2-u7-X17"},{"t":"③이 맨 앞에 와야 해요","mis":"K1-2-u7-X17"}],"explanation":["수목원에 먼저 가야 김밥을 먹어요.","②→①→③ 차례로 써요.","지도서 294쪽이에요."],"asset":{"type":"passage","lines":["① 점심시간에 김밥을 친구들과 나누어 먹었다.","② 친구들과 함께 버스를 타고 수목원으로 갔다.","③ 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"차례가 섞인 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#5','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'mc','auto','지도서 293쪽 — 「등굣길에 작년에 같은 반이었던 친구를 만난 일」을 글감으로 고른 까닭으로 알맞은 것은?',ARRAY['K1-2-u7-X09','K1-2-u7-X16']::text[],false,'{"seq":5,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"지도서 293쪽 — 「등굣길에 작년에 같은 반이었던 친구를 만난 일」을 글감으로 고른 까닭으로 알맞은 것은?","options":[{"t":"평범한 일이지만 반가웠고 하루 종일 즐거운 기분이 들어서","correct":true},{"t":"특별한 여행이라서","mis":"K1-2-u7-X09"},{"t":"친구가 쓰라고 해서","mis":"K1-2-u7-X16"}],"explanation":["평범한 일도 깊은 인상을 주면 글감이에요.","들려주고 싶은 까닭이 있어요.","지도서 293쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#6','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',3,'mc','auto','『국어활동』 85쪽 — 「기분이 좋았다.」를 생각이나 느낌이 잘 드러나게 고친 것은?',ARRAY['K1-2-u7-X11']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":3,"kind":"mc","stem":"『국어활동』 85쪽 — 「기분이 좋았다.」를 생각이나 느낌이 잘 드러나게 고친 것은?","options":[{"t":"②","correct":true},{"t":"①","mis":"K1-2-u7-X11"},{"t":"③","mis":"K1-2-u7-X11"}],"explanation":["②는 까닭(날씨)과 마음이 함께 있어요.","③은 같은 말만 늘어놓았어요.","국어활동 85쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["① 기분이 좋았다.","② 날씨가 너무 좋아 마음이 들뜨고 상쾌한 기분이 들었다.","③ 기분이 좋고 즐겁고 또 신나고 좋았다."],"title":"『국어활동』 85쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#7','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',3,'mc','auto','지도서 295쪽 — 돌려 읽기를 할 때 하지 않도록 하는 것은?',ARRAY['K1-2-u7-X18']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"지도서 295쪽 — 돌려 읽기를 할 때 하지 않도록 하는 것은?","options":[{"t":"틀린 글자를 고치는 데만 매달리기","correct":true},{"t":"친구 글에서 좋은 표현 찾기","mis":"K1-2-u7-X18"},{"t":"겪은 일과 느낌이 드러난 곳 칭찬하기","mis":"K1-2-u7-X18"}],"explanation":["틀린 글자에만 매달리지 않아요.","좋은 표현을 찾아 칭찬해요.","지도서 295쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#8','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',4,'sa','auto','『국어』 232쪽 보기 — 「친구가 나를 잡을까 봐 (      ).」 빈칸에 들어갈 마음말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C6","difficulty":4,"kind":"sa","stem":"『국어』 232쪽 보기 — 「친구가 나를 잡을까 봐 (      ).」 빈칸에 들어갈 마음말을 쓰세요.","answer":["조마조마했다","조마조마했어요"],"explanation":["「조마조마했다」예요.","「재미있었다」를 바꾼 말이에요.","232쪽 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#9','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C7',4,'essay','teacher','『국어』 233쪽 — 겪은 일과 그때의 마음이 잘 드러나게 자신이 겪은 일을 세 문장 이상 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"『국어』 233쪽 — 겪은 일과 그때의 마음이 잘 드러나게 자신이 겪은 일을 세 문장 이상 쓰세요.","answer_guide":{"answer":"예: 오늘 아침 등굣길에 친구들과 빨간 단풍잎을 주웠다. 바람이 불 때마다 잎이 빙글빙글 떨어져 신기했다. 가장 예쁜 잎을 공책에 끼우니 마음이 뿌듯했다. — 일이 일어난 차례와 다양한 마음말이 있으면 맞아요.","scoring_points":["겪은 일이 차례대로 있는가","그때의 마음을 다양한 말로 썼는가","세 문장 이상인가"]},"explanation":["231쪽에 정리한 내용을 바탕으로.","「재미있었다」로만 쓰지 않아요.","지도서 295쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L10_challenge#10','kor',1,2,'u7','L10','g1_2_kor_u7_L10_challenge','lesson_challenge','K1-2-u7-C6',4,'essay','teacher','『국어활동』 85쪽 — 「맛있었다」를 까닭을 넣어 자신의 경험으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":4,"kind":"essay","stem":"『국어활동』 85쪽 — 「맛있었다」를 까닭을 넣어 자신의 경험으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 내 생일날 아버지께서 끓여 주신 미역국에 밥을 말아 김치와 함께 먹으니 달콤한 사탕보다도 맛있었다. — 겪은 일과 맛있었던 까닭이 있으면 맞아요.","scoring_points":["겪은 일이 있는가","맛있었던 까닭이 있는가","완결된 문장인가"]},"explanation":["언제 무엇을 먹었는지 떠올려요.","까닭을 넣어요.","국어활동 85쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#1','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','칭찬하는 글로 쓰기에 알맞은 일은?',ARRAY['K1-2-u7-X16']::text[],false,'{"seq":1,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬하는 글로 쓰기에 알맞은 일은?","options":[{"t":"놀이 시간에 넘어진 나를 친구가 도와준 일","correct":true},{"t":"친구와 다툰 일","mis":"K1-2-u7-X16"},{"t":"친구가 지각한 일","mis":"K1-2-u7-X16"}],"explanation":["도움을 받은 일은 칭찬하기 좋아요.","234쪽 예시예요.","친구가 한 좋은 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#2','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','『국어』 234쪽 예시 — 언제 있었던 일인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":2,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"『국어』 234쪽 예시 — 언제 있었던 일인가요?","options":[{"t":"지난주 수요일 놀이 시간","correct":true},{"t":"어제 점심시간","mis":"K1-2-u7-X06"},{"t":"지난주 금요일 아침","mis":"K1-2-u7-X06"}],"explanation":["지난주 수요일 놀이 시간이에요.","첫 문장을 다시 읽어요.","234쪽이에요."],"asset":{"type":"passage","lines":["지난주 수요일 놀이 시간에 축구를 하던 나는 넘어져 다리를 많이 다쳤다.","옆에 있던 친구가 나를 보건실까지 데려다주었다.","축구를 좋아하는 친구가 축구도 멈추고 나를 도와주어 많이 고마웠다.","정말 착한 친구이다."],"title":"『국어』 234쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#3','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',1,'mc','auto','예시 글에서 친구가 한 일은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":3,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"예시 글에서 친구가 한 일은?","options":[{"t":"나를 보건실까지 데려다주었다","correct":true},{"t":"축구공을 빌려주었다","mis":"K1-2-u7-X06"},{"t":"숙제를 도와주었다","mis":"K1-2-u7-X06"}],"explanation":["보건실까지 데려다주었어요.","둘째 문장이에요.","234쪽이에요."],"asset":{"type":"passage","lines":["지난주 수요일 놀이 시간에 축구를 하던 나는 넘어져 다리를 많이 다쳤다.","옆에 있던 친구가 나를 보건실까지 데려다주었다.","축구를 좋아하는 친구가 축구도 멈추고 나를 도와주어 많이 고마웠다.","정말 착한 친구이다."],"title":"『국어』 234쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
