INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#6','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'mc','auto','칭찬하는 말로 알맞은 것은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":6,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 말로 알맞은 것은?","options":[{"t":"네가 나를 도와줘서 정말 고마웠어","correct":true},{"t":"너는 달리기가 느리지만 착해","mis":"K1-2-u7-X19"},{"t":"너는 축구를 못하더라","mis":"K1-2-u7-X19"}],"explanation":["진심 어린 칭찬이에요.","평가하는 말은 칭찬이 아니에요.","지도서 297쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#7','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'ox','auto','칭찬하는 글은 같은 반 친구에게만 쓸 수 있어요.',ARRAY['K1-2-u7-X20']::text[],false,'{"seq":7,"concept":"K1-2-u7-C8","difficulty":2,"kind":"ox","stem":"칭찬하는 글은 같은 반 친구에게만 쓸 수 있어요.","answer":"X","reason_options":[{"t":"가족·선생님·이웃에게도 쓸 수 있으니까","correct":true},{"t":"교과서에 친구만 나오니까","mis":"K1-2-u7-X20"}],"mis":"K1-2-u7-X20","explanation":["칭찬할 수 있는 모든 사람.","지도서 296쪽이에요.","가족·선생님도."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#8','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',2,'mc','auto','예시 글에서 그때의 마음이 가장 잘 드러난 문장은?',ARRAY['K1-2-u7-X12','K1-2-u7-X10']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"예시 글에서 그때의 마음이 가장 잘 드러난 문장은?","options":[{"t":"축구를 좋아하는 친구가 축구도 멈추고 나를 도와주어 많이 고마웠다","correct":true},{"t":"옆에 있던 친구가 나를 보건실까지 데려다주었다","mis":"K1-2-u7-X12"},{"t":"지난주 수요일 놀이 시간이었다","mis":"K1-2-u7-X10"}],"explanation":["무엇이 고마웠는지 까닭이 함께 있어요.","다른 문장은 한 일과 때예요.","234쪽이에요."],"asset":{"type":"passage","lines":["지난주 수요일 놀이 시간에 축구를 하던 나는 넘어져 다리를 많이 다쳤다.","옆에 있던 친구가 나를 보건실까지 데려다주었다.","축구를 좋아하는 친구가 축구도 멈추고 나를 도와주어 많이 고마웠다.","정말 착한 친구이다."],"title":"『국어』 234쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#9','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C7',2,'mc','auto','지도서 298쪽 — 영미는 철수 글에 이어 무엇을 썼나요?',ARRAY['K1-2-u7-X16']::text[],false,'{"seq":9,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"지도서 298쪽 — 영미는 철수 글에 이어 무엇을 썼나요?","options":[{"t":"무지개와 관련해 자신이 겪은 일","correct":true},{"t":"철수 글을 똑같이 따라 쓴 것","mis":"K1-2-u7-X16"},{"t":"무지개와 상관없는 일","mis":"K1-2-u7-X16"}],"explanation":["같은 화제로 자기 경험을 이었어요.","따라 쓰거나 다른 이야기를 쓰지 않아요.","지도서 298쪽이에요."],"asset":{"type":"speech","turns":[{"who":"철수","text":"나는 오늘 아침 등굣길에 무지개를 보았어. 비가 그친 파란 하늘에 생긴 일곱 색깔 무지개가 아름다운 보석처럼 보였어."},{"who":"영미","text":"나는 분무기로 물을 뿌려서 무지개를 만들어 본 적이 있어. 내 손으로 무지개를 만들 수 있다는 것이 신기했어."},{"who":"지영","text":"나는 무지개를 직접 보지는 못했지만 무지개 사진을 책에서 본 적이 있어. 정말 예쁜 무지개였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_basic#10','kor',1,2,'u7','L12','g1_2_kor_u7_L12_basic','lesson_basic','K1-2-u7-C8',3,'mc','auto','칭찬하는 글을 쓸 때 가장 중요한 것은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":10,"concept":"K1-2-u7-C8","difficulty":3,"kind":"mc","stem":"칭찬하는 글을 쓸 때 가장 중요한 것은?","options":[{"t":"왜 칭찬하는지 함께 겪은 일을 들어 써요","correct":true},{"t":"「착해」 한마디만 써요","mis":"K1-2-u7-X19"},{"t":"친구의 잘못도 함께 써요","mis":"K1-2-u7-X19"}],"explanation":["「왜」 칭찬받아야 하는지 써요.","지도서 296쪽이에요.","겪은 일을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#1','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C7',2,'mc','auto','지도서 298쪽 — 철수·영미·지영 글의 같은 화제는?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":1,"concept":"K1-2-u7-C7","difficulty":2,"kind":"mc","stem":"지도서 298쪽 — 철수·영미·지영 글의 같은 화제는?","options":[{"t":"무지개","correct":true},{"t":"분무기","mis":"K1-2-u7-X04"},{"t":"책","mis":"K1-2-u7-X04"}],"explanation":["셋 다 무지개 이야기예요.","분무기·책은 한 사람 글에만 나와요.","지도서 298쪽이에요."],"asset":{"type":"speech","turns":[{"who":"철수","text":"나는 오늘 아침 등굣길에 무지개를 보았어. 비가 그친 파란 하늘에 생긴 일곱 색깔 무지개가 아름다운 보석처럼 보였어."},{"who":"영미","text":"나는 분무기로 물을 뿌려서 무지개를 만들어 본 적이 있어. 내 손으로 무지개를 만들 수 있다는 것이 신기했어."},{"who":"지영","text":"나는 무지개를 직접 보지는 못했지만 무지개 사진을 책에서 본 적이 있어. 정말 예쁜 무지개였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
