INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#4','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'error','auto','한 친구가 쓴 칭찬하는 글이에요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X19','K1-2-u7-X10']::text[],false,'{"seq":4,"concept":"K1-2-u7-C8","difficulty":3,"kind":"error","stem":"한 친구가 쓴 칭찬하는 글이에요. 무엇이 아쉬운가요?","options":[{"t":"친구가 한 일이 빠졌어요 — 왜 칭찬하는지 알 수 없어요","correct":true,"mis_target":"K1-2-u7-X19"},{"t":"잘 썼어요","mis":"K1-2-u7-X19"},{"t":"언제가 너무 자세해요","mis":"K1-2-u7-X10"}],"explanation":["「착하다·최고다」만으로는 까닭을 몰라요.","친구가 한 일을 넣어요.","지도서 296쪽이에요."],"asset":{"type":"passage","lines":["어제 점심시간이었다.","내 짝은 정말 착하다.","최고다."],"title":"한 친구가 쓴 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#5','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'mc','auto','지도서 297쪽 대안 활동 — 친구 대신 칭찬하는 글을 쓸 수 있는 사람으로 알맞은 것은?',ARRAY['K1-2-u7-X20']::text[],false,'{"seq":5,"concept":"K1-2-u7-C8","difficulty":3,"kind":"mc","stem":"지도서 297쪽 대안 활동 — 친구 대신 칭찬하는 글을 쓸 수 있는 사람으로 알맞은 것은?","options":[{"t":"나 자신","correct":true},{"t":"아무도 없어요","mis":"K1-2-u7-X20"},{"t":"같은 반 친구만","mis":"K1-2-u7-X20"}],"explanation":["나에게 칭찬하는 글도 써요.","지도서 297쪽이에요.","나 자신도."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#6','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',3,'mc','auto','칭찬하는 글을 학급 게시판에 붙이면 좋은 점은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":6,"concept":"K1-2-u7-C8","difficulty":3,"kind":"mc","stem":"칭찬하는 글을 학급 게시판에 붙이면 좋은 점은?","options":[{"t":"친구들에게 더 관심을 기울이고 다른 친구의 본보기가 돼요","correct":true},{"t":"글자 수를 견줄 수 있어요","mis":"K1-2-u7-X19"},{"t":"누가 잘했는지 점수를 매길 수 있어요","mis":"K1-2-u7-X19"}],"explanation":["관심과 본보기가 돼요.","견주거나 점수 매기지 않아요.","지도서 296쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#7','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C7',3,'error','auto','한 친구가 쓴 칭찬하는 글이에요. 무엇이 잘못되었나요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":3,"kind":"error","stem":"한 친구가 쓴 칭찬하는 글이에요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 일이 일어난 차례가 섞였어요","correct":true,"mis_target":"K1-2-u7-X17"},{"t":"잘 썼어요","mis":"K1-2-u7-X17"},{"t":"③이 맨 앞에 와야 해요","mis":"K1-2-u7-X17"}],"explanation":["넘어진 뒤에 친구가 데려다주었어요.","②→①→③ 차례예요.","234쪽이에요."],"asset":{"type":"passage","lines":["① 옆에 있던 친구가 나를 보건실까지 데려다주었다.","② 놀이 시간에 축구를 하던 나는 넘어져 다리를 다쳤다.","③ 나를 도와주어 많이 고마웠다."],"title":"차례가 섞인 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#8','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',4,'sa','auto','『국어』 234쪽 표에서 「언제」, 「칭찬하고 싶은 일」 다음 칸의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":4,"kind":"sa","stem":"『국어』 234쪽 표에서 「언제」, 「칭찬하고 싶은 일」 다음 칸의 이름을 쓰세요.","answer":["그때의 마음","그때의마음"],"explanation":["「그때의 마음」이에요.","세 칸으로 정리해요.","234쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#9','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',4,'essay','teacher','『국어』 234쪽 ③ — 친구와 함께 했던 일을 떠올려 언제·칭찬하고 싶은 일·그때의 마음을 넣어 칭찬하는 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"『국어』 234쪽 ③ — 친구와 함께 했던 일을 떠올려 언제·칭찬하고 싶은 일·그때의 마음을 넣어 칭찬하는 글을 쓰세요.","answer_guide":{"answer":"예: 어제 미술 시간에 짝이 물감을 같이 써 주었다. 준비물을 잊어 걱정했는데 짝 덕분에 그림을 다 그려서 고마웠다. — 세 가지가 있고 평가하지 않았으면 맞아요.","scoring_points":["언제가 있는가","친구가 한 일이 있는가","그때의 마음이 있고 평가하지 않았는가"]},"explanation":["세 칸을 떠올려요.","진심 어린 칭찬.","지도서 297쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_L12_challenge#10','kor',1,2,'u7','L12','g1_2_kor_u7_L12_challenge','lesson_challenge','K1-2-u7-C8',4,'essay','teacher','가족이나 선생님 가운데 한 사람을 골라 겪은 일을 넣어 칭찬하는 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"가족이나 선생님 가운데 한 사람을 골라 겪은 일을 넣어 칭찬하는 글을 쓰세요.","answer_guide":{"answer":"예: 지난 토요일 할머니께서 내가 좋아하는 김밥을 싸 주셨다. 우엉이 짭조름해서 정말 맛있었고 할머니께 감사했다. — 언제·한 일·마음이 있으면 맞아요.","scoring_points":["칭찬할 사람이 있는가","그 사람이 한 일이 있는가","그때의 마음이 있는가"]},"explanation":["친구 말고도 칭찬할 수 있어요.","지도서 296쪽이에요.","한 일을 꼭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#1','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C1',1,'mc','auto','장난감 조립 설명서는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"장난감 조립 설명서는 무엇을 알려 주나요?","options":[{"t":"장난감을 어떻게 만드는지","correct":true},{"t":"장난감을 산 가게","mis":"K1-2-u7-X01"},{"t":"장난감 주인의 이름","mis":"K1-2-u7-X01"}],"explanation":["만드는 방법을 알려 줘요.","215쪽이에요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"scene","icon":"👧📄🧩","text":"『국어』 215쪽 — 아이가 종이를 펼쳐 보며 장난감 조각을 맞추고 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#2','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"독도","correct":true},{"t":"등대","mis":"K1-2-u7-X04"},{"t":"바위섬","mis":"K1-2-u7-X04"}],"explanation":["제목과 문장마다 독도가 나와요.","등대·바위섬은 독도의 일부예요.","제목과 되풀이 낱말."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#3','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C3',1,'mc','auto','「자연은 발명왕」 전체가 소개하는 것은 무엇인가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"「자연은 발명왕」 전체가 소개하는 것은 무엇인가요?","options":[{"t":"자연을 본떠 만든 물건","correct":true},{"t":"발명왕","mis":"K1-2-u7-X03"},{"t":"문어","mis":"K1-2-u7-X04"}],"explanation":["세 문단을 합쳐요.","발명왕은 제목의 말, 문어는 한 문단이에요.","문단을 합쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#4','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C4',1,'mc','auto','동도에 있는 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"동도에 있는 것은?","options":[{"t":"등대","correct":true},{"t":"주민 숙소","mis":"K1-2-u7-X06"},{"t":"물이 모이는 곳","mis":"K1-2-u7-X06"}],"explanation":["동도에는 등대·배 시설·경비대.","숙소·물은 서도예요.","219쪽이에요."],"asset":{"type":"passage","lines":["동도에는 등대와, 배가 드나들 수 있도록 만든 시설이 있습니다.","동도에 있는 등대는 밤에도 불을 밝혀 독도 주변을 지키는 데 도움을 줍니다.","독도를 지키는 경비대도 이곳에 있습니다."],"title":"「독도」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#5','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C5',1,'mc','auto','준수가 잃어버린 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"준수가 잃어버린 것은?","options":[{"t":"필통","correct":true},{"t":"운동화","mis":"K1-2-u7-X06"},{"t":"모자","mis":"K1-2-u7-X06"}],"explanation":["준수는 필통을 잃어버렸어요.","간추림 첫 줄이에요.","224쪽이에요."],"asset":{"type":"passage","lines":["준수는 필통을 잃어버려서 연필도 모두 사라졌어요.","필통을 잃어버린 것이 벌써 세 번째라 엄마께 또 사 달라고 하기가 걱정되었어요.","준수는 엄마와 약속을 하고 겨우 새 필통을 샀어요.","새 필통에는 큼직한 이름표를 붙였어요.","집에 와서 보니 필통은 가방에 그대로 있었어요.","그런데 이번에는 알림장이 보이지 않았어요."],"title":"「진짜 일 학년 책가방을 지켜라!」(신순재 글) 간추림 — 『국어』 224~228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
