INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#11','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C1',2,'mc','auto','「무엇을 자르지?」 하고 묻던 아이가 만들기를 잘하려면?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":11,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"「무엇을 자르지?」 하고 묻던 아이가 만들기를 잘하려면?","options":[{"t":"설명을 듣고 무엇을 어떻게 하라는 것인지 이해해야 해요","correct":true},{"t":"빨리 만들어야 해요","mis":"K1-2-u7-X02"},{"t":"마음대로 만들어요","mis":"K1-2-u7-X02"}],"explanation":["설명을 이해해야 해요.","217쪽 예시 답안이에요.","잘 듣기."],"asset":{"type":"speech","turns":[{"who":"화면","text":"접은 색종이를 가위로 자르세요."},{"who":"여자아이","text":"무엇을 자르지?"},{"who":"남자아이","text":"아하, 이번에는 색종이를 반으로 잘라야 하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#12','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',2,'mc','auto','설명하는 대상을 찾는 방법으로 알맞은 것은?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":12,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"설명하는 대상을 찾는 방법으로 알맞은 것은?","options":[{"t":"제목을 살펴보고 되풀이해 나오는 낱말을 찾아요","correct":true},{"t":"마지막 낱말만 봐요","mis":"K1-2-u7-X05"},{"t":"사진 색깔만 봐요","mis":"K1-2-u7-X05"}],"explanation":["제목과 되풀이 낱말이 실마리예요.","지도서 283쪽이에요.","두 가지 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#13','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C3',2,'ox','auto','「자연은 발명왕」은 제목에 문어·민들레씨 같은 대상이 바로 나와요.',ARRAY['K1-2-u7-X03']::text[],false,'{"seq":13,"concept":"K1-2-u7-C3","difficulty":2,"kind":"ox","stem":"「자연은 발명왕」은 제목에 문어·민들레씨 같은 대상이 바로 나와요.","answer":"X","reason_options":[{"t":"글을 읽어야 무엇을 알려 주는지 알 수 있으니까","correct":true},{"t":"「발명왕」이 바로 대상이니까","mis":"K1-2-u7-X03"}],"mis":"K1-2-u7-X03","explanation":["제목에 구체적인 대상은 없어요.","지도서 286쪽이에요.","문단을 합쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
