INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#15','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C5',2,'ox','auto','겪은 일을 떠올릴 때에는 특별한 일만 골라야 해요.',ARRAY['K1-2-u7-X09']::text[],false,'{"seq":15,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"겪은 일을 떠올릴 때에는 특별한 일만 골라야 해요.","answer":"X","reason_options":[{"t":"날마다 있는 일도 겪은 일이니까","correct":true},{"t":"특별한 일만 글로 쓸 수 있으니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["평범한 일도 좋아요.","지도서 288쪽이에요.","일상에서."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
