INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#17','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C3',3,'error','auto','한 친구가 「「자연은 발명왕」은 문어를 설명해요.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":17,"concept":"K1-2-u7-C3","difficulty":3,"kind":"error","stem":"한 친구가 「「자연은 발명왕」은 문어를 설명해요.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"첫 문단만 보았어요 — 합치면 자연을 본떠 만든 물건이에요","correct":true,"mis_target":"K1-2-u7-X04"},{"t":"잘 말했어요","mis":"K1-2-u7-X04"},{"t":"「발명왕」이라고 해야 해요","mis":"K1-2-u7-X03"}],"explanation":["문어는 한 문단에만 나와요.","문단을 합쳐요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
