INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#19','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C5',3,'error','auto','한 친구가 정리한 겪은 일이에요. 무엇이 빠졌나요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":19,"concept":"K1-2-u7-C5","difficulty":3,"kind":"error","stem":"한 친구가 정리한 겪은 일이에요. 무엇이 빠졌나요?","options":[{"t":"그때의 마음이 빠졌어요","correct":true,"mis_target":"K1-2-u7-X10"},{"t":"잘 정리했어요","mis":"K1-2-u7-X10"},{"t":"언제가 빠졌어요","mis":"K1-2-u7-X10"}],"explanation":["마음을 더해요.","229쪽 3번이에요.","칸을 채워요."],"asset":{"type":"passage","lines":["언제: 어제 아침","어디에서: 교실","무슨 일: 준비물을 가져오지 못했어요."],"title":"한 친구가 정리한 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#20','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C6',3,'error','auto','마음을 나타낸 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#21','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C7',3,'error','auto','한 친구가 쓴 글이에요. 무엇이 잘못되었나요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":21,"concept":"K1-2-u7-C7","difficulty":3,"kind":"error","stem":"한 친구가 쓴 글이에요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 차례가 섞였어요","correct":true,"mis_target":"K1-2-u7-X17"},{"t":"잘 썼어요","mis":"K1-2-u7-X17"},{"t":"③이 맨 앞에 와야 해요","mis":"K1-2-u7-X17"}],"explanation":["②→①→③.","일이 일어난 차례대로.","지도서 294쪽이에요."],"asset":{"type":"passage","lines":["① 점심시간에 김밥을 친구들과 나누어 먹었다.","② 친구들과 함께 버스를 타고 수목원으로 갔다.","③ 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"차례가 섞인 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#22','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C4',3,'mc','auto','로봇이 인간 대신 할 수 있다고 한 일은?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":22,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"로봇이 인간 대신 할 수 있다고 한 일은?","options":[{"t":"온도가 너무 높거나 낮은 위험한 곳에서 일하기","correct":true},{"t":"사람 대신 잠자기","mis":"K1-2-u7-X07"},{"t":"사람과 놀아 주기","mis":"K1-2-u7-X07"}],"explanation":["글에 적힌 일이에요.","지도서 303쪽이에요.","줄을 짚어요."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#23','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C2',4,'sa','auto','이 글이 설명하는 대상을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"이 글이 설명하는 대상을 쓰세요.","answer":["독도"],"explanation":["독도예요.","제목과 되풀이 낱말.","219쪽이에요."],"asset":{"type":"passage","lines":["독도는 우리나라 동쪽 끝에 위치한 섬입니다.","독도는 큰 섬 두 개와 작은 바위섬 89개로 이루어져 있습니다.","큰 섬 두 개를 각각 동도와 서도라고 부릅니다.","독도는 동도와 서도를 모두 합쳐 부르는 이름입니다."],"title":"「독도」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#24','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C3',4,'essay','teacher','지도서 303쪽 평가 — 글을 읽고 무엇을 설명하는지 생각하고 정리해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C3","difficulty":4,"kind":"essay","stem":"지도서 303쪽 평가 — 글을 읽고 무엇을 설명하는지 생각하고 정리해 보세요.","answer_guide":{"answer":"예: 이 글은 로봇을 설명해요. 로봇은 쉬지 않고 일할 수 있고, 위험한 곳에서 인간 대신 일할 수 있어요. — 로봇이 무엇인지와 대신할 수 있는 일을 정리하면 맞아요.","scoring_points":["설명하는 대상을 썼는가","글에 있는 내용으로 정리했는가","완결된 문장인가"]},"explanation":["제목·되풀이 낱말로 대상을 찾아요.","무엇을 대신하는지 정리해요.","지도서 302쪽 평가의 중점이에요."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_a#25','kor',1,2,'u7','','g1_2_kor_u7_review_a','unit_review','K1-2-u7-C7',4,'essay','teacher','지도서 305쪽 평가 — 언제·누구와·왜 그런 일이 일어났는지·어떤 생각이나 느낌이 들었는지 생각하며 겪은 일을 글로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"지도서 305쪽 평가 — 언제·누구와·왜 그런 일이 일어났는지·어떤 생각이나 느낌이 들었는지 생각하며 겪은 일을 글로 쓰세요.","answer_guide":{"answer":"예: 어제 점심시간에 친구들과 운동장에서 낙엽 잡기를 했다. 바람이 불 때마다 잎이 춤추듯 떨어져 잡기 어려웠다. 하나도 못 잡아 섭섭했지만 친구들과 웃으며 놀아서 즐거웠다. — 네 물음의 답과 다양한 마음말이 있으면 맞아요.","scoring_points":["언제·누구와가 있는가","일이 일어난 까닭과 차례가 있는가","생각이나 느낌을 풍부하게 썼는가"]},"explanation":["네 물음에 답하며 써요.","단순한 서술을 넘어 마음을.","지도서 304쪽 평가의 중점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#1','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C1',1,'mc','auto','음식 만들기 재료에 든 설명서는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"음식 만들기 재료에 든 설명서는 무엇을 알려 주나요?","options":[{"t":"음식을 어떻게 만드는지","correct":true},{"t":"재료를 산 날짜","mis":"K1-2-u7-X01"},{"t":"음식을 먹을 사람","mis":"K1-2-u7-X01"}],"explanation":["만드는 방법을 알려 줘요.","217쪽이에요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"집에 음식 만들기 재료가 배달되었는데, 엄마께서 거기에 있는 설명서를 따라 음식을 만드시는 것을 본 적이 있어."},{"who":"친구 2","text":"나는 아빠께서 새로 산 청소기를 설명서를 따라서 조립하시는 것을 본 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#2','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"비사치기","correct":true},{"t":"가위바위보","mis":"K1-2-u7-X04"},{"t":"줄","mis":"K1-2-u7-X04"}],"explanation":["제목과 첫 문장에 비사치기가 나와요.","가위바위보·줄은 놀이 속 한 부분이에요.","제목과 되풀이 낱말."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#3','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',1,'mc','auto','이 글이 설명하는 대상은 무엇인가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"이 글이 설명하는 대상은 무엇인가요?","options":[{"t":"문어","correct":true},{"t":"요술쟁이","mis":"K1-2-u7-X03"},{"t":"모래","mis":"K1-2-u7-X04"}],"explanation":["모든 문장이 문어 이야기예요.","요술쟁이는 제목의 말, 모래는 한 문장이에요.","문단을 합쳐요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#4','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C4',1,'mc','auto','비사치기에 쓰는 것은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"비사치기에 쓰는 것은?","options":[{"t":"손바닥만 한 돌멩이","correct":true},{"t":"공","mis":"K1-2-u7-X06"},{"t":"줄넘기","mis":"K1-2-u7-X06"}],"explanation":["평평하고 잘 세워지는 돌멩이예요.","둘째 문장이에요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#5','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C5',1,'mc','auto','예시 글은 어디에서 있었던 일인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"예시 글은 어디에서 있었던 일인가요?","options":[{"t":"수목원","correct":true},{"t":"바닷가","mis":"K1-2-u7-X06"},{"t":"놀이공원","mis":"K1-2-u7-X06"}],"explanation":["수목원에서 있었던 일이에요.","첫 문단이에요.","233쪽이에요."],"asset":{"type":"passage","lines":["1학년이 되어서 처음으로 현장 체험 학습을 갔다. 친구들과 함께 버스를 타고 수목원으로 갔다.","수목원에는 큰 나무와 예쁜 꽃이 많았다.","‘오리나무’와 ‘꽝꽝나무’는 이름이 너무 재미있었다.","화살나무는 줄기가 화살처럼 생겨 신기했다.","점심시간에는 할머니께서 싸 주신 김밥을 친구들과 나누어 먹었다.","김밥 안에 있는 우엉이 달콤하고 짭조름했다.","친구들과 술래잡기도 했다. 친구가 나를 잡을까 봐 조마조마했다.","신나게 놀고 나니 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"『국어』 233쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#6','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C6',1,'mc','auto','『국어』 238쪽 — 이 표정에 어울리지 않는 낱말은?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"『국어』 238쪽 — 이 표정에 어울리지 않는 낱말은?","options":[{"t":"귀찮아요","correct":true},{"t":"신기해요","mis":"K1-2-u7-X13"},{"t":"놀라워요","mis":"K1-2-u7-X13"}],"explanation":["눈이 동그래진 얼굴에는 귀찮아요가 어울리지 않아요.","신기해요·놀라워요는 어울려요.","238쪽이에요."],"asset":{"type":"scene","icon":"😲","text":"눈이 동그래진 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#7','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C7',1,'mc','auto','글감이 될 수 있는 겪은 일은?',ARRAY['K1-2-u7-X08','K1-2-u7-X16']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"글감이 될 수 있는 겪은 일은?","options":[{"t":"등굣길에 친구들과 단풍잎을 본 일","correct":true},{"t":"다음 주에 갈 여행","mis":"K1-2-u7-X08"},{"t":"책에서 읽은 남의 이야기","mis":"K1-2-u7-X16"}],"explanation":["평범한 일도 글감이에요.","지도서 294쪽이에요.","이미 있었던 내 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#8','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',1,'mc','auto','칭찬하는 글에 쓰기 알맞은 일은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬하는 글에 쓰기 알맞은 일은?","options":[{"t":"준비물을 잊은 나에게 친구가 물감을 같이 써 준 일","correct":true},{"t":"친구의 필통이 예쁜 것","mis":"K1-2-u7-X19"},{"t":"친구가 나보다 글씨가 느린 것","mis":"K1-2-u7-X19"}],"explanation":["친구가 한 좋은 일이에요.","겉모습·견주기는 칭찬거리가 아니에요.","지도서 297쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#9','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C4',2,'match','auto','자연과 본떠 만든 물건을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":2,"kind":"match","stem":"자연과 본떠 만든 물건을 이어 보세요.","pairs":[{"l":"문어의 빨판","r":"칫솔걸이"},{"l":"민들레씨","r":"낙하산"},{"l":"도꼬마리 열매","r":"신발 끈"}],"mis":"K1-2-u7-X06","explanation":["문단마다 하나씩.","220~222쪽이에요.","글에 적힌 대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#10','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C6',2,'match','auto','예시 글의 장면과 마음을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"예시 글의 장면과 마음을 이어 보세요.","pairs":[{"l":"화살나무를 보았어요","r":"신기했어요"},{"l":"술래잡기를 했어요","r":"조마조마했어요"},{"l":"집에 가야 했어요","r":"아쉬웠어요"}],"mis":"K1-2-u7-X13","explanation":["장면마다 마음이 달라요.","233쪽이에요.","장면을 떠올려요."],"asset":{"type":"passage","lines":["1학년이 되어서 처음으로 현장 체험 학습을 갔다. 친구들과 함께 버스를 타고 수목원으로 갔다.","수목원에는 큰 나무와 예쁜 꽃이 많았다.","‘오리나무’와 ‘꽝꽝나무’는 이름이 너무 재미있었다.","화살나무는 줄기가 화살처럼 생겨 신기했다.","점심시간에는 할머니께서 싸 주신 김밥을 친구들과 나누어 먹었다.","김밥 안에 있는 우엉이 달콤하고 짭조름했다.","친구들과 술래잡기도 했다. 친구가 나를 잡을까 봐 조마조마했다.","신나게 놀고 나니 선생님께서 집에 가야 한다고 하셨다. 더 놀고 싶었는데 아쉬웠다."],"title":"『국어』 233쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#11','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C1',2,'mc','auto','「아하, 이번에는 색종이를 반으로 잘라야 하는구나.」 한 아이가 잘한 것은?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":11,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"「아하, 이번에는 색종이를 반으로 잘라야 하는구나.」 한 아이가 잘한 것은?","options":[{"t":"설명을 잘 듣고 무엇을 할지 알았어요","correct":true},{"t":"가위를 빨리 집었어요","mis":"K1-2-u7-X02"},{"t":"친구 것을 따라 했어요","mis":"K1-2-u7-X02"}],"explanation":["설명을 이해했어요.","216쪽이에요.","잘 듣기."],"asset":{"type":"speech","turns":[{"who":"화면","text":"접은 색종이를 가위로 자르세요."},{"who":"여자아이","text":"무엇을 자르지?"},{"who":"남자아이","text":"아하, 이번에는 색종이를 반으로 잘라야 하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#12','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C2',2,'mc','auto','「비사치기」에서 설명하는 대상을 알 수 있는 실마리는?',ARRAY['K1-2-u7-X05','K1-2-u7-X04']::text[],false,'{"seq":12,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"「비사치기」에서 설명하는 대상을 알 수 있는 실마리는?","options":[{"t":"제목과 첫 문장에 나온 「비사치기」","correct":true},{"t":"마지막 문장의 「이깁니다」","mis":"K1-2-u7-X05"},{"t":"셋째 문장의 「줄」","mis":"K1-2-u7-X04"}],"explanation":["제목과 첫 문장이 실마리예요.","한 번 나온 말은 대상이 아니에요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#13','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',2,'mc','auto','「요술쟁이 바다 생물」에서 「요술쟁이」가 가리키는 것은?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":13,"concept":"K1-2-u7-C3","difficulty":2,"kind":"mc","stem":"「요술쟁이 바다 생물」에서 「요술쟁이」가 가리키는 것은?","options":[{"t":"몸 색깔을 바꾸는 문어","correct":true},{"t":"마술사","mis":"K1-2-u7-X03"},{"t":"모래","mis":"K1-2-u7-X04"}],"explanation":["색깔을 바꾸는 문어를 요술쟁이라 했어요.","제목을 글과 이어 봐요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#14','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C6',2,'mc','auto','「김밥이 맛있었다.」를 바꾸어 쓴 것은?',ARRAY['K1-2-u7-X12','K1-2-u7-X11']::text[],false,'{"seq":14,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"「김밥이 맛있었다.」를 바꾸어 쓴 것은?","options":[{"t":"짭조름한 우엉이 많아서 김밥이 맛있었다","correct":true},{"t":"김밥을 먹었다","mis":"K1-2-u7-X12"},{"t":"맛있었다 맛있었다","mis":"K1-2-u7-X11"}],"explanation":["까닭이 들어 있어요.","232쪽 예시 답안이에요.","다양한 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#15','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C5',2,'ox','auto','겪은 일을 정리할 때에는 언제, 어디에서 있었던 일인지 생각해요.',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":15,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"겪은 일을 정리할 때에는 언제, 어디에서 있었던 일인지 생각해요.","answer":"O","reason_options":[{"t":"그래야 무슨 일이었는지 잘 드러나니까","correct":true},{"t":"언제·어디는 중요하지 않으니까","mis":"K1-2-u7-X10"}],"mis":"K1-2-u7-X10","explanation":["언제·어디에서·그때의 마음.","229쪽 3번이에요.","칸을 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#16','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',2,'mc','auto','칭찬하는 말로 알맞은 것은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":16,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 말로 알맞은 것은?","options":[{"t":"준비물을 나누어 써 줘서 그림을 끝까지 그릴 수 있었어, 고마워","correct":true},{"t":"너는 나보다 그림을 잘 그려","mis":"K1-2-u7-X19"},{"t":"착해","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 있어요.","견주거나 뭉뚱그리지 않아요.","지도서 297쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#17','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',3,'error','auto','한 친구가 「「자연은 발명왕」은 발명왕이라는 사람을 설명해요.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":17,"concept":"K1-2-u7-C3","difficulty":3,"kind":"error","stem":"한 친구가 「「자연은 발명왕」은 발명왕이라는 사람을 설명해요.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"제목 낱말만 보았어요 — 문단을 읽으면 자연을 본떠 만든 물건이에요","correct":true,"mis_target":"K1-2-u7-X03"},{"t":"잘 말했어요","mis":"K1-2-u7-X03"},{"t":"민들레씨라고 해야 해요","mis":"K1-2-u7-X04"}],"explanation":["제목만 보고 답하지 않아요.","문단을 함께 읽어요.","지도서 286쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
