INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#21','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C7',3,'mc','auto','232쪽 보기 글과 233쪽 예시 글 가운데 겪은 일과 마음이 더 잘 드러난 글은?',ARRAY['K1-2-u7-X14','K1-2-u7-X11']::text[],false,'{"seq":21,"concept":"K1-2-u7-C7","difficulty":3,"kind":"mc","stem":"232쪽 보기 글과 233쪽 예시 글 가운데 겪은 일과 마음이 더 잘 드러난 글은?","options":[{"t":"예시 글 — 그때의 마음을 다양한 말로 썼어요","correct":true},{"t":"보기 글 — 짧아서 읽기 쉬워요","mis":"K1-2-u7-X14"},{"t":"둘 다 똑같아요","mis":"K1-2-u7-X11"}],"explanation":["예시 글은 장면마다 마음이 있어요.","짧은 것이 잘 쓴 것은 아니에요.","233쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#22','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C4',3,'mc','auto','「비사치기」에서 가위바위보를 하여 진 편이 하는 일은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":22,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"「비사치기」에서 가위바위보를 하여 진 편이 하는 일은?","options":[{"t":"준비한 돌멩이를 줄 위에 세워 놓아요","correct":true},{"t":"상대의 돌을 넘어뜨려요","mis":"K1-2-u7-X06"},{"t":"땅에 줄을 그어요","mis":"K1-2-u7-X06"}],"explanation":["진 편은 돌을 세워요.","넘어뜨리는 것은 이긴 편이에요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#23','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',4,'sa','auto','제목에 나오지 않지만 이 글이 설명하는 대상을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C3","difficulty":4,"kind":"sa","stem":"제목에 나오지 않지만 이 글이 설명하는 대상을 쓰세요.","answer":["문어"],"explanation":["문어예요.","요술쟁이는 문어를 빗댄 말.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#24','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C3',4,'essay','teacher','「독도」를 읽고 무엇을 설명하는지 생각하고 정리해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C3","difficulty":4,"kind":"essay","stem":"「독도」를 읽고 무엇을 설명하는지 생각하고 정리해 보세요.","answer_guide":{"answer":"예: 이 글은 독도를 설명해요. 독도는 동쪽 끝에 있고, 동도에는 등대가, 서도에는 주민 숙소가 있어요. — 대상과 글에 있는 내용이 있으면 맞아요.","scoring_points":["설명하는 대상을 썼는가","글에 있는 내용으로 정리했는가","완결된 문장인가"]},"explanation":["대상을 먼저 써요.","동도·서도를 헷갈리지 않아요.","219쪽이에요."],"asset":{"type":"passage","lines":["동도에는 등대와, 배가 드나들 수 있도록 만든 시설이 있습니다.","동도에 있는 등대는 밤에도 불을 밝혀 독도 주변을 지키는 데 도움을 줍니다.","독도를 지키는 경비대도 이곳에 있습니다."],"title":"「독도」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_b#25','kor',1,2,'u7','','g1_2_kor_u7_review_b','unit_review','K1-2-u7-C8',4,'essay','teacher','친구와 함께 했던 일을 떠올려 언제·칭찬하고 싶은 일·그때의 마음을 넣어 칭찬하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C8","difficulty":4,"kind":"essay","stem":"친구와 함께 했던 일을 떠올려 언제·칭찬하고 싶은 일·그때의 마음을 넣어 칭찬하는 글을 쓰세요.","answer_guide":{"answer":"예: 지난 금요일 체육 시간에 줄넘기 줄이 엉켰는데 짝이 함께 풀어 주었다. 덕분에 끝까지 넘을 수 있어서 고마웠다. — 세 가지가 있고 평가하지 않았으면 맞아요.","scoring_points":["언제가 있는가","친구가 한 일이 있는가","그때의 마음이 있고 평가하지 않았는가"]},"explanation":["세 칸.","진심 어린 칭찬.","234쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#1','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C1',1,'mc','auto','새로 산 청소기의 설명서는 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"새로 산 청소기의 설명서는 무엇을 알려 주나요?","options":[{"t":"청소기를 어떻게 조립하는지","correct":true},{"t":"청소기의 색깔 이름","mis":"K1-2-u7-X01"},{"t":"청소기를 산 사람","mis":"K1-2-u7-X01"}],"explanation":["조립하는 방법을 알려 줘요.","217쪽이에요.","읽고 나서 무엇을 할 수 있나요?"],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"집에 음식 만들기 재료가 배달되었는데, 엄마께서 거기에 있는 설명서를 따라 음식을 만드시는 것을 본 적이 있어."},{"who":"친구 2","text":"나는 아빠께서 새로 산 청소기를 설명서를 따라서 조립하시는 것을 본 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#2','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',1,'mc','auto','이 글은 무엇을 설명하나요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"이 글은 무엇을 설명하나요?","options":[{"t":"로봇","correct":true},{"t":"휴식","mis":"K1-2-u7-X04"},{"t":"온도","mis":"K1-2-u7-X04"}],"explanation":["문장마다 로봇이 나와요.","휴식·온도는 한 문장에만 나와요.","제목과 되풀이 낱말."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#3','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C3',1,'mc','auto','『국어활동』 83쪽 — 「사진을 예의 있게 찍는 방법」이 무엇을 설명하는지 알기 위해 생각한 것으로 바르지 않은 것은?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"『국어활동』 83쪽 — 「사진을 예의 있게 찍는 방법」이 무엇을 설명하는지 알기 위해 생각한 것으로 바르지 않은 것은?","options":[{"t":"사진을 찍을 때 얼마나 빛이 나는지 생각해 봐야 해","correct":true},{"t":"제목에 있는 낱말 「사진」과 「예의」를 생각해 봐야 해","mis":"K1-2-u7-X05"},{"t":"무엇을 알려 주려는지 생각해 봐야 해","mis":"K1-2-u7-X05"}],"explanation":["빛은 설명하는 대상과 상관없어요.","제목 낱말과 알려 주려는 것을 생각해요.","국어활동 83쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#4','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C4',1,'mc','auto','이 글에서 로봇은 무엇이라고 했나요?',ARRAY['K1-2-u7-X07']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"이 글에서 로봇은 무엇이라고 했나요?","options":[{"t":"어떤 일을 자동으로 하는 기계 장치","correct":true},{"t":"사람이 타는 자동차","mis":"K1-2-u7-X07"},{"t":"살아 있는 동물","mis":"K1-2-u7-X07"}],"explanation":["첫 문장에 있어요.","글에 없는 것은 고르지 않아요.","지도서 303쪽이에요."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#5','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C5',1,'mc','auto','칭찬 예시 글은 언제 있었던 일인가요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"칭찬 예시 글은 언제 있었던 일인가요?","options":[{"t":"지난주 수요일 놀이 시간","correct":true},{"t":"어제 아침","mis":"K1-2-u7-X06"},{"t":"지난 일요일","mis":"K1-2-u7-X06"}],"explanation":["지난주 수요일 놀이 시간이에요.","첫 문장이에요.","234쪽이에요."],"asset":{"type":"passage","lines":["지난주 수요일 놀이 시간에 축구를 하던 나는 넘어져 다리를 많이 다쳤다.","옆에 있던 친구가 나를 보건실까지 데려다주었다.","축구를 좋아하는 친구가 축구도 멈추고 나를 도와주어 많이 고마웠다.","정말 착한 친구이다."],"title":"『국어』 234쪽 예시 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#6','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C6',1,'mc','auto','『국어』 238쪽 — 이 표정에 어울리지 않는 낱말은?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"『국어』 238쪽 — 이 표정에 어울리지 않는 낱말은?","options":[{"t":"신나요","correct":true},{"t":"슬퍼요","mis":"K1-2-u7-X13"},{"t":"서러워요","mis":"K1-2-u7-X13"}],"explanation":["우는 얼굴에는 신나요가 어울리지 않아요.","슬퍼요·서러워요는 어울려요.","238쪽이에요."],"asset":{"type":"scene","icon":"😢","text":"눈물을 흘리는 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#7','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',1,'mc','auto','글감이 될 수 있는 겪은 일은?',ARRAY['K1-2-u7-X08','K1-2-u7-X16']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"글감이 될 수 있는 겪은 일은?","options":[{"t":"현장 체험 학습을 간 일","correct":true},{"t":"내년에 할 운동회","mis":"K1-2-u7-X08"},{"t":"동생이 혼자 겪은 일","mis":"K1-2-u7-X16"}],"explanation":["내가 겪은 일이에요.","231쪽 보기예요.","이미 있었던 내 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#8','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C8',1,'mc','auto','칭찬하는 글에 쓰기 알맞은 일은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬하는 글에 쓰기 알맞은 일은?","options":[{"t":"어머니께서 아침마다 웃으며 배웅해 주신 일","correct":true},{"t":"어머니의 가방이 새것인 것","mis":"K1-2-u7-X19"},{"t":"어머니가 옆집보다 키가 큰 것","mis":"K1-2-u7-X19"}],"explanation":["가족에게도 칭찬할 수 있어요.","한 일을 칭찬해요.","지도서 296쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#9','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C4',2,'match','auto','『국어』 237쪽 — 낱말과 설명을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":2,"kind":"match","stem":"『국어』 237쪽 — 낱말과 설명을 이어 보세요.","pairs":[{"l":"나눠 쓰기","r":"필요 없는 물건을 나누어 주는 것"},{"l":"바꿔 쓰기","r":"서로 필요한 물건을 바꾸어 쓰는 것"},{"l":"다시 쓰기","r":"버리지 않고 다시 쓰는 것"}],"mis":"K1-2-u7-X06","explanation":["대화에서 설명한 대로.","237쪽 예시 답안이에요.","글에 적힌 대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#10','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C6',2,'match','auto','겪은 일과 그때의 마음을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"겪은 일과 그때의 마음을 이어 보세요.","pairs":[{"l":"준비물을 가져오지 못했어요","r":"당황했어요"},{"l":"낙엽을 하나도 못 잡았어요","r":"섭섭했어요"},{"l":"친구들과 신나게 놀았어요","r":"좋았어요"}],"mis":"K1-2-u7-X13","explanation":["어울리는 마음을 이어요.","230쪽이에요.","장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#11','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C1',2,'mc','auto','설명서를 대충 읽으면 어떤 일이 생길까요?',ARRAY['K1-2-u7-X02']::text[],false,'{"seq":11,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"설명서를 대충 읽으면 어떤 일이 생길까요?","options":[{"t":"무엇을 어떻게 하는지 몰라 잘못 만들 수 있어요","correct":true},{"t":"더 빨리 잘 만들어요","mis":"K1-2-u7-X02"},{"t":"아무 일도 없어요","mis":"K1-2-u7-X02"}],"explanation":["차례대로 자세히 읽어요.","지도서 281쪽이에요.","꼼꼼히."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#12','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',2,'mc','auto','로봇 글에서 가장 많이 되풀이되는 낱말은?',ARRAY['K1-2-u7-X05']::text[],false,'{"seq":12,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"로봇 글에서 가장 많이 되풀이되는 낱말은?","options":[{"t":"로봇","correct":true},{"t":"휴식","mis":"K1-2-u7-X05"},{"t":"온도","mis":"K1-2-u7-X05"}],"explanation":["로봇이 문장마다 나와요.","휴식·온도는 한두 번이에요.","지도서 303쪽이에요."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#13','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C3',2,'mc','auto','제목 「자연은 발명왕」은 무엇을 뜻할까요?',ARRAY['K1-2-u7-X03']::text[],false,'{"seq":13,"concept":"K1-2-u7-C3","difficulty":2,"kind":"mc","stem":"제목 「자연은 발명왕」은 무엇을 뜻할까요?","options":[{"t":"자연을 본떠 여러 가지 물건을 만들 수 있다는 뜻","correct":true},{"t":"발명왕이라는 사람의 이름","mis":"K1-2-u7-X03"},{"t":"자연이 상을 받았다는 뜻","mis":"K1-2-u7-X03"}],"explanation":["문단 내용과 제목을 이어요.","지도서 286쪽이에요.","제목의 뜻."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#14','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C6',2,'mc','auto','「김밥이 맛있었다.」를 다르게 바꾸어 쓴 것은?',ARRAY['K1-2-u7-X12','K1-2-u7-X11']::text[],false,'{"seq":14,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"「김밥이 맛있었다.」를 다르게 바꾸어 쓴 것은?","options":[{"t":"고소한 냄새가 솔솔 나서 김밥이 맛있었다","correct":true},{"t":"김밥을 쌌다","mis":"K1-2-u7-X12"},{"t":"김밥이 좋았다","mis":"K1-2-u7-X11"}],"explanation":["냄새를 넣어 맛이 느껴져요.","232쪽 예시 답안이에요.","다양한 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#15','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C5',2,'ox','auto','아직 하지 않은 일도 겪은 일이에요.',ARRAY['K1-2-u7-X08']::text[],false,'{"seq":15,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"아직 하지 않은 일도 겪은 일이에요.","answer":"X","reason_options":[{"t":"겪은 일은 이미 있었던 일이니까","correct":true},{"t":"하고 싶은 일도 겪은 일이니까","mis":"K1-2-u7-X08"}],"mis":"K1-2-u7-X08","explanation":["이미 있었던 일이에요.","어제·오늘·지난번.","지도서 288쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#16','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C8',2,'mc','auto','칭찬하는 말로 알맞은 것은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":16,"concept":"K1-2-u7-C8","difficulty":2,"kind":"mc","stem":"칭찬하는 말로 알맞은 것은?","options":[{"t":"할머니, 김밥을 싸 주셔서 친구들과 맛있게 나누어 먹었어요","correct":true},{"t":"할머니 옷이 제일 예뻐요","mis":"K1-2-u7-X19"},{"t":"최고예요","mis":"K1-2-u7-X19"}],"explanation":["한 일과 마음이 있어요.","겉모습·뭉뚱그린 말은 아쉬워요.","지도서 296쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#17','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C3',3,'error','auto','한 친구가 「이 글은 요술쟁이를 설명해요.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X03','K1-2-u7-X04']::text[],false,'{"seq":17,"concept":"K1-2-u7-C3","difficulty":3,"kind":"error","stem":"한 친구가 「이 글은 요술쟁이를 설명해요.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"제목 낱말만 보았어요 — 글을 읽으면 문어예요","correct":true,"mis_target":"K1-2-u7-X03"},{"t":"잘 말했어요","mis":"K1-2-u7-X03"},{"t":"모래라고 해야 해요","mis":"K1-2-u7-X04"}],"explanation":["요술쟁이는 문어를 빗댄 말이에요.","글 내용을 함께 봐요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#18','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C4',3,'error','auto','친구들이 로봇 글을 읽고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#19','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C5',3,'error','auto','한 친구가 정리한 겪은 일이에요. 무엇이 빠졌나요?',ARRAY['K1-2-u7-X10']::text[],false,'{"seq":19,"concept":"K1-2-u7-C5","difficulty":3,"kind":"error","stem":"한 친구가 정리한 겪은 일이에요. 무엇이 빠졌나요?","options":[{"t":"언제가 빠졌어요","correct":true,"mis_target":"K1-2-u7-X10"},{"t":"잘 정리했어요","mis":"K1-2-u7-X10"},{"t":"그때의 마음이 빠졌어요","mis":"K1-2-u7-X10"}],"explanation":["언제 있었던 일인지 더해요.","229쪽 3번이에요.","칸을 채워요."],"asset":{"type":"passage","lines":["어디에서: 운동장","무슨 일: 친구들과 낙엽 잡기를 했어요.","그때의 마음: 섭섭했지만 신났어요."],"title":"한 친구가 정리한 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
