INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#21','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',3,'error','auto','돌려 읽기를 할 때 할 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#22','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C4',3,'mc','auto','바위 주변에 있는 문어는 어떻게 하나요?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":22,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"바위 주변에 있는 문어는 어떻게 하나요?","options":[{"t":"몸을 바위와 같은 색깔로 바꿔요","correct":true},{"t":"모래 속으로 숨어요","mis":"K1-2-u7-X06"},{"t":"먹물을 뿜어요","mis":"K1-2-u7-X07"}],"explanation":["바위 색으로 바꿔요.","먹물 이야기는 글에 없어요.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#23','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C2',4,'sa','auto','이 글이 설명하는 대상을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"이 글이 설명하는 대상을 쓰세요.","answer":["로봇"],"explanation":["로봇이에요.","문장마다 나와요.","지도서 303쪽이에요."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#24','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C3',4,'essay','teacher','「자연은 발명왕」을 읽고 무엇을 설명하는지 생각하고 정리해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C3","difficulty":4,"kind":"essay","stem":"「자연은 발명왕」을 읽고 무엇을 설명하는지 생각하고 정리해 보세요.","answer_guide":{"answer":"예: 이 글은 자연을 본떠 만든 물건을 설명해요. 문어 빨판으로 칫솔걸이를, 민들레씨로 낙하산을 만들었어요. — 글 전체가 설명하는 것과 예가 있으면 맞아요.","scoring_points":["글 전체가 설명하는 것을 썼는가","글에 있는 예를 들었는가","완결된 문장인가"]},"explanation":["문단을 합쳐요.","예를 하나 이상.","223쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_c#25','kor',1,2,'u7','','g1_2_kor_u7_review_c','unit_review','K1-2-u7-C7',4,'essay','teacher','『국어』 233쪽 예시 글처럼, 학교에서 겪은 일 하나를 골라 일이 일어난 차례대로 그때의 마음을 넣어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C7","difficulty":4,"kind":"essay","stem":"『국어』 233쪽 예시 글처럼, 학교에서 겪은 일 하나를 골라 일이 일어난 차례대로 그때의 마음을 넣어 쓰세요.","answer_guide":{"answer":"예: 오늘 급식 시간에 처음 시금치를 먹어 보았다. 처음에는 쓴맛이 날까 봐 걱정되었다. 꼭꼭 씹어 보니 고소해서 깜짝 놀랐다. 선생님께서 칭찬해 주셔서 뿌듯했다. — 차례와 장면마다의 마음이 있으면 맞아요.","scoring_points":["평범한 일도 글감으로 골랐는가","일이 일어난 차례대로 썼는가","마음을 다양한 말로 썼는가"]},"explanation":["평범한 일도 좋아요.","차례대로.","지도서 292쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#1','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C1',1,'mc','auto','놀이판에 적힌 놀이 방법은 무엇을 알려 주나요?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":1,"concept":"K1-2-u7-C1","difficulty":1,"kind":"mc","stem":"놀이판에 적힌 놀이 방법은 무엇을 알려 주나요?","options":[{"t":"놀이를 어떻게 하는지","correct":true},{"t":"놀이판을 만든 사람","mis":"K1-2-u7-X01"},{"t":"놀이판의 무게","mis":"K1-2-u7-X01"}],"explanation":["놀이하는 방법을 알려 줘요.","지도서 280쪽이에요.","읽고 나서 무엇을 할 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#2','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',1,'mc','auto','두 친구의 대화에서 설명하는 것은 무엇인가요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":2,"concept":"K1-2-u7-C2","difficulty":1,"kind":"mc","stem":"두 친구의 대화에서 설명하는 것은 무엇인가요?","options":[{"t":"아나바다","correct":true},{"t":"놀이","mis":"K1-2-u7-X04"},{"t":"동네","mis":"K1-2-u7-X04"}],"explanation":["「아나바다」가 되풀이해 나와요.","놀이·동네는 한 번 나온 말이에요.","되풀이 낱말."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나, 우리 동네에서 열리는 아나바다 행사에 가려고 하는데 같이 갈래?"},{"who":"친구 2","text":"응? 그게 뭐야?"},{"who":"친구 1","text":"‘아껴 쓰고, 나눠 쓰고, 바꿔 쓰고, 다시 쓰고’의 앞 글자만 따서 부르는 거야."},{"who":"친구 1","text":"나에게 필요가 없지만, 다른 사람에게는 필요한 물건을 나누어 주는 거야."},{"who":"친구 2","text":"서로에게 필요한 물건을 바꾸어 쓰는 것은 바꿔 쓰기구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#3','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C3',1,'mc','auto','「자연은 발명왕」 세 문단에 공통으로 나오는 이야기는?',ARRAY['K1-2-u7-X04','K1-2-u7-X03']::text[],false,'{"seq":3,"concept":"K1-2-u7-C3","difficulty":1,"kind":"mc","stem":"「자연은 발명왕」 세 문단에 공통으로 나오는 이야기는?","options":[{"t":"자연을 본떠 물건을 만들었다는 이야기","correct":true},{"t":"문어가 바다에 산다는 이야기","mis":"K1-2-u7-X04"},{"t":"발명왕이 상을 받았다는 이야기","mis":"K1-2-u7-X03"}],"explanation":["문단마다 자연과 본뜬 물건이 나와요.","한 문단·제목 낱말만 보지 않아요.","문단을 합쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#4','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C4',1,'mc','auto','대화에서 「나눠 쓰기」는 무엇이라고 했나요?',ARRAY['K1-2-u7-X06','K1-2-u7-X07']::text[],false,'{"seq":4,"concept":"K1-2-u7-C4","difficulty":1,"kind":"mc","stem":"대화에서 「나눠 쓰기」는 무엇이라고 했나요?","options":[{"t":"나에게 필요 없는 물건을 나누어 주는 것","correct":true},{"t":"서로 필요한 물건을 바꾸어 쓰는 것","mis":"K1-2-u7-X06"},{"t":"물건을 버리는 것","mis":"K1-2-u7-X07"}],"explanation":["필요한 사람에게 나누어 줘요.","바꾸어 쓰는 것은 바꿔 쓰기예요.","236쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나, 우리 동네에서 열리는 아나바다 행사에 가려고 하는데 같이 갈래?"},{"who":"친구 2","text":"응? 그게 뭐야?"},{"who":"친구 1","text":"‘아껴 쓰고, 나눠 쓰고, 바꿔 쓰고, 다시 쓰고’의 앞 글자만 따서 부르는 거야."},{"who":"친구 1","text":"나에게 필요가 없지만, 다른 사람에게는 필요한 물건을 나누어 주는 거야."},{"who":"친구 2","text":"서로에게 필요한 물건을 바꾸어 쓰는 것은 바꿔 쓰기구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#5','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C5',1,'mc','auto','이 친구는 누구와 함께 무엇을 했나요?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":5,"concept":"K1-2-u7-C5","difficulty":1,"kind":"mc","stem":"이 친구는 누구와 함께 무엇을 했나요?","options":[{"t":"친구들과 함께 낙엽 잡기를 했어요","correct":true},{"t":"가족과 함께 소풍을 갔어요","mis":"K1-2-u7-X06"},{"t":"혼자 그림을 그렸어요","mis":"K1-2-u7-X06"}],"explanation":["친구들과 낙엽 잡기를 했어요.","230쪽 말풍선이에요.","누구와·무슨 일."],"asset":{"type":"speech","turns":[{"who":"친구","text":"오늘 친구들과 함께 바람에 떨어지는 낙엽 잡기를 했어. 낙엽을 하나도 못 잡은 건 섭섭하지만, 친구들과 신나게 놀 수 있어서 좋았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#6','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',1,'mc','auto','『국어』 238쪽 — 이 표정에 어울리지 않는 낱말은?',ARRAY['K1-2-u7-X13']::text[],false,'{"seq":6,"concept":"K1-2-u7-C6","difficulty":1,"kind":"mc","stem":"『국어』 238쪽 — 이 표정에 어울리지 않는 낱말은?","options":[{"t":"슬퍼요","correct":true},{"t":"화나요","mis":"K1-2-u7-X13"},{"t":"못마땅해요","mis":"K1-2-u7-X13"}],"explanation":["찌푸린 얼굴에는 화나요·못마땅해요가 어울려요.","못마땅해요는 마음에 들지 않는다는 뜻이에요.","238쪽이에요."],"asset":{"type":"scene","icon":"😠","text":"눈썹을 찌푸린 얼굴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#7','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C7',1,'mc','auto','글감이 될 수 있는 겪은 일은?',ARRAY['K1-2-u7-X08','K1-2-u7-X16']::text[],false,'{"seq":7,"concept":"K1-2-u7-C7","difficulty":1,"kind":"mc","stem":"글감이 될 수 있는 겪은 일은?","options":[{"t":"운동장에서 노란 은행잎을 주운 일","correct":true},{"t":"하고 싶은 일","mis":"K1-2-u7-X08"},{"t":"뉴스에 나온 이야기","mis":"K1-2-u7-X16"}],"explanation":["평범한 일도 글감이에요.","지도서 294쪽이에요.","이미 있었던 내 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#8','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C8',1,'mc','auto','칭찬하는 글에 쓰기 알맞은 일은?',ARRAY['K1-2-u7-X19']::text[],false,'{"seq":8,"concept":"K1-2-u7-C8","difficulty":1,"kind":"mc","stem":"칭찬하는 글에 쓰기 알맞은 일은?","options":[{"t":"선생님께서 우리 반 사진을 찍어 주신 일","correct":true},{"t":"선생님의 안경이 멋진 것","mis":"K1-2-u7-X19"},{"t":"선생님이 다른 반 선생님보다 젊은 것","mis":"K1-2-u7-X19"}],"explanation":["선생님께도 칭찬할 수 있어요.","한 일을 칭찬해요.","지도서 296쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#9','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C4',2,'match','auto','로봇 글을 읽고 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u7-C4","difficulty":2,"kind":"match","stem":"로봇 글을 읽고 알맞게 이어 보세요.","pairs":[{"l":"휴식","r":"로봇은 필요하지 않아요"},{"l":"위험한 곳","r":"로봇이 인간 대신 일해요"},{"l":"앞으로","r":"여러 분야에서 인간을 대신해요"}],"mis":"K1-2-u7-X06","explanation":["글에 적힌 대로.","지도서 303쪽이에요.","줄을 짚어요."],"asset":{"type":"passage","lines":["로봇은 어떤 일을 자동으로 하는 기계 장치입니다.","로봇은 쉬지 않고 인간이 하는 일을 대신할 수 있습니다.","인간은 일을 할 때 휴식이 필요합니다. 그러나 로봇은 휴식이 필요하지 않고 계속 일할 수 있습니다.","또 로봇은 위험한 일을 인간 대신 할 수 있습니다.","온도가 너무 높거나 낮아 인간이 일하기 위험한 곳에서 로봇은 인간 대신 일을 할 수 있습니다.","앞으로 로봇은 여러 분야에서 인간을 대신해 일을 하게 될 것입니다."],"title":"지도서 303쪽 평가 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#10','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',2,'match','auto','『국어활동』 85쪽 — 겪은 일과 그때의 마음을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u7-C6","difficulty":2,"kind":"match","stem":"『국어활동』 85쪽 — 겪은 일과 그때의 마음을 이어 보세요.","pairs":[{"l":"날씨가 너무 좋았어요","r":"상쾌했어요"},{"l":"수학 시간에 카드 놀이를 했어요","r":"수학 공부가 더 흥미로웠어요"},{"l":"미역국에 밥을 말아 먹었어요","r":"사탕보다도 맛있었어요"}],"mis":"K1-2-u7-X13","explanation":["까닭과 마음이 함께 있어요.","국어활동 85쪽 예시 답안이에요.","장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#11','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C1',2,'mc','auto','아빠께서 설명서를 따라 청소기를 조립하신 까닭은?',ARRAY['K1-2-u7-X01']::text[],false,'{"seq":11,"concept":"K1-2-u7-C1","difficulty":2,"kind":"mc","stem":"아빠께서 설명서를 따라 청소기를 조립하신 까닭은?","options":[{"t":"청소기를 어떻게 조립하는지 알기 위해서","correct":true},{"t":"설명서를 모으려고","mis":"K1-2-u7-X01"},{"t":"청소기 색을 바꾸려고","mis":"K1-2-u7-X01"}],"explanation":["설명서는 방법을 알려 줘요.","217쪽이에요.","무엇을 알려 주나."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"집에 음식 만들기 재료가 배달되었는데, 엄마께서 거기에 있는 설명서를 따라 음식을 만드시는 것을 본 적이 있어."},{"who":"친구 2","text":"나는 아빠께서 새로 산 청소기를 설명서를 따라서 조립하시는 것을 본 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#12','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',2,'mc','auto','제목만 보고 설명하는 대상을 정하면 안 되는 까닭은?',ARRAY['K1-2-u7-X05','K1-2-u7-X03']::text[],false,'{"seq":12,"concept":"K1-2-u7-C2","difficulty":2,"kind":"mc","stem":"제목만 보고 설명하는 대상을 정하면 안 되는 까닭은?","options":[{"t":"제목에 대상이 드러나지 않는 글도 있으니까","correct":true},{"t":"제목은 늘 틀리니까","mis":"K1-2-u7-X05"},{"t":"제목이 곧 대상이니까 봐도 돼요","mis":"K1-2-u7-X03"}],"explanation":["「자연은 발명왕」처럼요.","제목과 글 내용을 함께 봐요.","지도서 282쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#13','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C3',2,'mc','auto','아껴 쓰기·나눠 쓰기·바꿔 쓰기·다시 쓰기를 합치면 무엇에 대한 이야기인가요?',ARRAY['K1-2-u7-X06','K1-2-u7-X04']::text[],false,'{"seq":13,"concept":"K1-2-u7-C3","difficulty":2,"kind":"mc","stem":"아껴 쓰기·나눠 쓰기·바꿔 쓰기·다시 쓰기를 합치면 무엇에 대한 이야기인가요?","options":[{"t":"물건을 소중히 쓰는 방법","correct":true},{"t":"물건을 많이 사는 방법","mis":"K1-2-u7-X06"},{"t":"놀이하는 방법","mis":"K1-2-u7-X04"}],"explanation":["네 가지를 합쳐요.","236쪽이에요.","합쳐서 생각해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나, 우리 동네에서 열리는 아나바다 행사에 가려고 하는데 같이 갈래?"},{"who":"친구 2","text":"응? 그게 뭐야?"},{"who":"친구 1","text":"‘아껴 쓰고, 나눠 쓰고, 바꿔 쓰고, 다시 쓰고’의 앞 글자만 따서 부르는 거야."},{"who":"친구 1","text":"나에게 필요가 없지만, 다른 사람에게는 필요한 물건을 나누어 주는 거야."},{"who":"친구 2","text":"서로에게 필요한 물건을 바꾸어 쓰는 것은 바꿔 쓰기구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#14','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',2,'mc','auto','지도서 295쪽 — 「재미있었다.」를 바꾸어 쓴 것은?',ARRAY['K1-2-u7-X12','K1-2-u7-X11']::text[],false,'{"seq":14,"concept":"K1-2-u7-C6","difficulty":2,"kind":"mc","stem":"지도서 295쪽 — 「재미있었다.」를 바꾸어 쓴 것은?","options":[{"t":"알록달록한 꽃들 속에서 숨바꼭질을 하니 신이 났다","correct":true},{"t":"숨바꼭질을 했다","mis":"K1-2-u7-X12"},{"t":"재미있었다 재미있었다","mis":"K1-2-u7-X11"}],"explanation":["장면과 마음이 함께 있어요.","지도서 295쪽 활동 예시예요.","다양한 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#15','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C5',2,'ox','auto','다른 사람과 비슷한 마음이 들었던 내 경험을 떠올려도 돼요.',ARRAY['K1-2-u7-X09']::text[],false,'{"seq":15,"concept":"K1-2-u7-C5","difficulty":2,"kind":"ox","stem":"다른 사람과 비슷한 마음이 들었던 내 경험을 떠올려도 돼요.","answer":"O","reason_options":[{"t":"비슷한 마음이 든 일도 내가 겪은 일이니까","correct":true},{"t":"남과 똑같은 일만 떠올려야 하니까","mis":"K1-2-u7-X09"}],"mis":"K1-2-u7-X09","explanation":["비슷한 일도, 비슷한 마음도.","230쪽 말풍선이에요.","내 경험."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
