INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#17','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',3,'error','auto','한 친구가 「「독도」는 등대를 설명해요.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u7-X04']::text[],false,'{"seq":17,"concept":"K1-2-u7-C2","difficulty":3,"kind":"error","stem":"한 친구가 「「독도」는 등대를 설명해요.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"동도 문단만 보았어요 — 글 전체는 독도를 설명해요","correct":true,"mis_target":"K1-2-u7-X04"},{"t":"잘 말했어요","mis":"K1-2-u7-X04"},{"t":"「동도」라고 해야 해요","mis":"K1-2-u7-X04"}],"explanation":["등대는 한 문단에만 나와요.","제목과 되풀이 낱말은 독도예요.","219쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
