INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#21','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C7',3,'error','auto','한 친구가 쓴 칭찬하는 글이에요. 무엇이 잘못되었나요?',ARRAY['K1-2-u7-X17']::text[],false,'{"seq":21,"concept":"K1-2-u7-C7","difficulty":3,"kind":"error","stem":"한 친구가 쓴 칭찬하는 글이에요. 무엇이 잘못되었나요?","options":[{"t":"②가 맨 앞에 와야 해요 — 차례가 섞였어요","correct":true,"mis_target":"K1-2-u7-X17"},{"t":"잘 썼어요","mis":"K1-2-u7-X17"},{"t":"③이 맨 앞에 와야 해요","mis":"K1-2-u7-X17"}],"explanation":["넘어진 뒤에 도움을 받았어요.","②→①→③.","234쪽이에요."],"asset":{"type":"passage","lines":["① 옆에 있던 친구가 나를 보건실까지 데려다주었다.","② 놀이 시간에 축구를 하던 나는 넘어져 다리를 다쳤다.","③ 나를 도와주어 많이 고마웠다."],"title":"차례가 섞인 칭찬하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#22','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C4',3,'mc','auto','독도관리사무소 직원이 독도에 올 때 이용하는 곳은?',ARRAY['K1-2-u7-X06']::text[],false,'{"seq":22,"concept":"K1-2-u7-C4","difficulty":3,"kind":"mc","stem":"독도관리사무소 직원이 독도에 올 때 이용하는 곳은?","options":[{"t":"서도의 숙소","correct":true},{"t":"동도의 등대","mis":"K1-2-u7-X06"},{"t":"동도의 경비대","mis":"K1-2-u7-X06"}],"explanation":["서도 숙소를 이용해요.","등대·경비대는 동도예요.","219쪽이에요."],"asset":{"type":"passage","lines":["서도에는 주민을 위한 숙소가 있습니다.","독도를 사람들에게 널리 알리고 보존하는 일을 하는 독도관리사무소 직원도 독도에 올 때에는 이곳을 이용합니다.","또 서도에는 땅에 스며든 물이 땅 밖으로 모이는 곳이 있습니다.","옛날에는 사람들이 이 물을 썼지만, 요즘은 바닷물을 우리가 먹을 수 있게 바꾼 뒤 그 물을 사용합니다."],"title":"「독도」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#23','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C2',4,'sa','auto','이 글이 설명하는 대상을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u7-C2","difficulty":4,"kind":"sa","stem":"이 글이 설명하는 대상을 쓰세요.","answer":["비사치기"],"explanation":["비사치기예요.","제목과 첫 문장.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["비사치기는 돌멩이를 이용한 놀이입니다.","먼저, 평평하고 잘 세워지는 손바닥만 한 돌멩이를 준비합니다.","두 편을 나누고 땅바닥에 줄을 긋습니다.","가위바위보를 하여 진 편은 준비한 돌멩이를 줄 위에 세워 놓습니다.","이긴 편은 한 사람씩 나와 자신의 돌을 가지고 상대의 돌을 넘어뜨립니다.","돌은 발등이나 배 위에 올려 옮길 수도 있고, 무릎 사이에 끼워 옮길 수도 있습니다.","세워 놓은 상대의 돌멩이를 다 넘어뜨리면 이깁니다."],"title":"「비사치기」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#24','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C3',4,'essay','teacher','「요술쟁이 바다 생물」을 읽고 무엇을 설명하는지 생각하고 정리해 보세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u7-C3","difficulty":4,"kind":"essay","stem":"「요술쟁이 바다 생물」을 읽고 무엇을 설명하는지 생각하고 정리해 보세요.","answer_guide":{"answer":"예: 이 글은 문어를 설명해요. 문어는 몸 색깔을 주변과 비슷하게 바꾸어 위험을 피하고 먹이를 잡아요. — 대상과 글에 있는 내용이 있으면 맞아요.","scoring_points":["설명하는 대상을 썼는가","글에 있는 내용으로 정리했는가","완결된 문장인가"]},"explanation":["제목에 속지 않아요.","문어가 무엇을 하는지.","지도서 287쪽이에요."],"asset":{"type":"passage","lines":["문어는 바닷속에서 매우 특이한 능력을 가지고 살아가는 해양 생물 가운데 하나입니다.","이들은 자신의 몸 형태와 색깔을 바꾸어서 주변 환경과 비슷하게 보이게 하는 능력이 있습니다.","바닷속에 모래가 많다면 문어는 몸을 모래와 똑같은 색깔로 바꿔 보이지 않게 합니다.","바위 주변에 있다면 몸을 바위와 같은 색깔로 바꿔서 보이지 않게 합니다.","이렇게 문어는 자신의 몸을 위장함으로써 위험을 피하고 먹이를 쉽게 잡습니다."],"title":"「요술쟁이 바다 생물」 (지도서 287쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u7_review_d#25','kor',1,2,'u7','','g1_2_kor_u7_review_d','unit_review','K1-2-u7-C6',4,'essay','teacher','「재미있었다」, 「즐거웠다」를 쓰지 않고 자신이 겪은 일 하나와 그때의 마음을 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u7-C6","difficulty":4,"kind":"essay","stem":"「재미있었다」, 「즐거웠다」를 쓰지 않고 자신이 겪은 일 하나와 그때의 마음을 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 어제 수학 시간에 친구랑 카드 놀이를 했다. 내 차례가 올 때마다 가슴이 두근두근했다. 수학 공부가 더 흥미롭게 느껴졌다. — 「재미있었다·즐거웠다」 없이 까닭 있는 마음말이 있으면 맞아요.","scoring_points":["겪은 일이 있는가","「재미있었다·즐거웠다」를 쓰지 않았는가","마음의 까닭이 있는가"]},"explanation":["까닭을 넣은 다른 마음말.","국어활동 85쪽이에요.","다양한 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
